function teamMul(e){var m=1;S.emp.forEach(function(x){if(x===e||!(x.rank==='lead'||x.rank==='mgr')||x.sick>0||x.st==='home'||x.st==='out'||x.st==='errandWait')return;var g=x.sk.G||0;/* Management skill now has a meaningful team-wide impact. */m+=x.rank==='mgr'?.18+.05*g:.12+.04*g});return Math.min(2,m)}
function selfMul(e){return e.rank==='spec'?1.25:e.rank==='lead'?.85:e.rank==='mgr'?.7:1}
function evMul(e){return powerWorkMultiplier()*teamMul(e)*selfMul(e)}
function promoList(e){var L=[],n=S.emp.length,lv=el(e),top=Math.max.apply(null,KS.map(function(k){return e.sk[k]})),
 leads=S.emp.filter(function(x){return x.rank==='lead'}).length,mgrs=S.emp.filter(function(x){return x.rank==='mgr'}).length;
 if(!e.rank){var slotL=leads+mgrs<Math.max(1,Math.floor(n/3));
  L.push({r:'lead',cost:3000,ok:lv>=2&&e.sk.G>=3&&slotL,need:'ต้อง Lv2 + Management 3'+(slotL?'':' · ตำแหน่งเต็ม')});
  L.push({r:'spec',cost:4000,ok:lv>=3&&top>=6,need:'ต้อง Lv3 + ทักษะหลัก 6'})}
 else if(e.rank==='lead'){var slotM=mgrs<Math.max(1,Math.floor(n/6));
  L.push({r:'mgr',cost:10000,ok:lv>=5&&e.sk.G>=7&&slotM,need:'ต้อง Lv5 + Management 7'+(slotM?'':' · ตำแหน่งเต็ม')})}
 return L}
function promoBtns(e){return promoList(e).map(function(p){return '<button class="btn" '+(p.ok?'':'disabled')+' onclick="A.promote('+e.id+',\''+p.r+'\')">เลื่อนเป็น '+RANKN[p.r]+'<br><small>'+(p.ok?M(p.cost)+' · เงินเดือน +'+Math.round((RANKM[p.r]/(RANKM[e.rank]||1)-1)*100)+'%':p.need)+'</small></button>'}).join('')}
function rankTag(e){return (e.rank?' <span style="color:#fbbf24">'+RANKN[e.rank]+'</span>':'')+(e.sick>0?' <span style="color:#f87171">🤒 ลาป่วย '+e.sick+' วัน</span>':'')}
function rankInfo(e){var g=e.sk.G,t='';if(e.rank==='lead')t='เพิ่มความเร็วและผลงานให้เพื่อนร่วมทีม +'+Math.round((.12+.04*g)*100)+'% (Management G'+g+') และได้ EXP มากขึ้น (งานของตัวเอง −15%)';else if(e.rank==='mgr')t='เพิ่มความเร็วและผลงานให้เพื่อนร่วมทีม +'+Math.round((.18+.05*g)*100)+'% (Management G'+g+') และได้ EXP มากขึ้น (งานของตัวเอง −30%)';else if(e.rank==='spec')t='ผลงานของตัวเอง +25%';else return '';return '<br><small style="color:#fbbf24">'+t+'</small>'}
function evAsk(title,text,opts){var old=S.paused;S.paused=1;var d=document.createElement('div');d.id='evModal';
 var p=document.createElement('div');p.className='evFrame';
 p.innerHTML='<div class="evContent"><h2 class="evTitle">'+title+'</h2><div class="evMessage">'+text+'</div><div class="evActions"></div></div>';
 var actions=p.querySelector('.evActions');
 opts.forEach(function(o){var b=document.createElement('button');b.className='btn evAction';b.innerHTML=o.label;b.onclick=function(){if(o.fn&&o.fn()===false)return;d.remove();S.paused=old;show()};actions.appendChild(b)});
 d.appendChild(p);document.body.appendChild(d)}
function evLeave(e,why){S.emp=S.emp.filter(function(x){return x!==e});S.emp.forEach(function(x){x.ha=cl(x.ha-8)});S.rep=Math.max(0,S.rep-3);if(sel==e.id)sel=0;log(why)}
function evPoach(e){var X=Math.max(2000,Math.round(e.sal*2/100)*100),nm=e.name.replace(/[&<>"]/g,''),t=RANKN[e.rank]||'หัวหน้าทีม';
 evAsk('💼 '+t+'ถูกซื้อตัว!','บริษัทคู่แข่งยื่นข้อเสนอเงินเดือนสูงให้ <b>'+nm+'</b> ('+t+') ถ้าเขาไป เพื่อนร่วมทีมจะเสียกำลังใจและโบนัสทีมจะหายไป',[
 {label:'💰 ขึ้นเงินเดือน 20% + โบนัสรั้งตัว '+M(X)+'<br><small>รับรองอยู่ต่อแน่นอน</small>',fn:function(){if(!pay(X,'eq'))return false;e.rz=(e.rz||0)+.2;e.sal=salf(e);e.ha=cl(e.ha+10);log('✅ รั้ง '+e.name+' ไว้ได้ เงินเดือนขึ้นเป็น '+M(e.sal))}},
 {label:'🤝 ต่อรองแบบประหยัด '+M(X/2)+'<br><small>โอกาสสำเร็จ 55% ถ้าไม่สำเร็จเขาจะไปและเสียเงินเปล่า</small>',fn:function(){if(!pay(X/2,'eq'))return false;if(Math.random()<.55){e.rz=(e.rz||0)+.1;e.sal=salf(e);e.ha=cl(e.ha+5);log('✅ ต่อรองสำเร็จ '+e.name+' อยู่ต่อ')}else evLeave(e,'😢 '+e.name+' ย้ายไปบริษัทคู่แข่ง')}},
 {label:'👋 ปล่อยให้ไป',fn:function(){evLeave(e,'😢 '+e.name+' ถูกซื้อตัวไปบริษัทคู่แข่ง')}}])}
function evStart(t,force){if(!S.evq)S.evq=[];
 if(t==='blk'){S.blk={day:S.day,at:force?S.t:rnd(540,840),left:rnd(90,180),on:0}}
 else if(t==='sick'){var h=S.emp.filter(function(e){return !(e.sick>0)}).sort(function(a,b){return (b.sr+rnd(0,60))-(a.sr+rnd(0,60))});if(!h.length){if(force)toast('ไม่มีพนักงานให้ป่วย');return}
  var n=h.length>=5&&Math.random()<.35?2:1;for(var i=0;i<n;i++){var e=h[i];e.sick=rnd(1,3);if(e.st!=='home')exitP(e);log('🤒 '+e.name+' ป่วย ลาพัก '+e.sick+' วันทำงาน')}}
 else if(t==='poach'){var l=S.emp.filter(function(e){return e.rank==='lead'||e.rank==='mgr'});if(!l.length){if(force)toast('ต้องมีหัวหน้าทีมก่อน');return}S.evq.push({k:'poach',id:pick(l).id})}}
function evDaily(){if(!S.evq)S.evq=[];
 if((S.day-2)%7<5)S.emp.forEach(function(e){if(e.sick>0){e.sick--;if(e.sick<=0){e.sick=0;log('😀 '+e.name+' หายป่วยแล้ว')}}});
 /* Random workplace incidents are locked during the tutorial/early game and unlock from Day 11. */if(S.day<=10||S.day<(S.evNext||11))return;
 var wk=(S.day-1)%7<5,o=[],hl=S.emp.filter(function(e){return !(e.sick>0)}).length;
 if(wk)o.push(['blk',3]);if(wk&&hl)o.push(['sick',4]);if(S.emp.some(function(e){return e.rank==='lead'||e.rank==='mgr'})&&!S.evq.length)o.push(['poach',2]);
 if(!o.length)return;var tot=o.reduce(function(a,x){return a+x[1]},0),r=Math.random()*tot,t=o[0][0];for(var i=0;i<o.length;i++){if(r<o[i][1]){t=o[i][0];break}r-=o[i][1]}
 S.evNext=S.day+rnd(3,6);evStart(t,false)}
function evBlackoutChoice(b){
 evAsk(b.mafia?'🔌 ยากูซ่าตัดไฟบริษัท!':'⚡ ไฟดับ! จะจัดการอย่างไรดี?',b.mafia?'ลูกน้องริวจิตัดสายไฟก่อนเดินออกไป พนักงานทำงานไม่ได้จนกว่าไฟจะกลับมา เลือกวิธีแก้ไขสถานการณ์':'ระบบไฟฟ้าของบริษัทขัดข้อง พนักงานไม่สามารถทำงานได้ตามปกติ เลือกวิธีแก้ไขสถานการณ์',[
 {label:'🔧 เรียกช่างฉุกเฉิน จ่าย '+M(3500)+'<br><small>ซ่อมเหตุขัดข้องนี้ทันที แต่บิลค้างชำระยังต้องจ่ายแยก</small>',fn:function(){if(!pay(3500,'eq'))return false;if(b.mafia){powerOutageOff('mafia');powerOutageOff('event')}else powerOutageOff('event');S.blk=null;log(powerIsOff()?'🔧 ซ่อมเหตุไฟดับสำเร็จ แต่ไฟยังถูกตัดจาก: '+powerOutageLabel():'🔧 ซ่อมไฟฟ้าสำเร็จ ไฟกลับมาแล้ว')}},
 {label:'🔋 ซื้อเครื่องปั่นไฟสำรอง '+M(9000)+'<br><small>พนักงานทำงานได้ 50% ระหว่างเหตุไฟดับ แต่คอมพิวเตอร์/ระบบไฟยังถือว่าดับ</small>',fn:function(){if(!pay(9000,'eq'))return false;b.backup=1;powerGridState().backup=true;log('🔋 เปิดใช้เครื่องปั่นไฟสำรอง พนักงานทำงานได้ 50% ระหว่างไฟดับ')}},
 {label:'⏳ รอการไฟฟ้า ไม่เสียเงิน<br><small>รอให้เหตุไฟดับนี้หมดเวลา บิลค้างชำระยังคงอยู่</small>',fn:function(){log('⏳ เลือกรอให้เหตุไฟดับนี้หมดเวลา')}}])
}
function evTick(dm){var b=S.blk;
 if(b){if(!b.on){if(S.day===b.day&&S.t>=b.at){b.on=1;b.choiceShown=1;powerOutageOn(b.mafia?'mafia':'event');S.emp.forEach(function(e){e.ha=cl(e.ha-2)});log(b.mafia?'🔌 ยากูซ่าตัดไฟบริษัท! คอมพิวเตอร์ใช้ไม่ได้ ทุกคนทำงานไม่ได้':'⚡ ไฟดับ! คอมพิวเตอร์ใช้ไม่ได้ ทุกคนทำงานไม่ได้ชั่วคราว');evBlackoutChoice(b)}else if(S.day>b.day){if(b.mafia)powerOutageOff('mafia');else powerOutageOff('event');S.blk=null}}
  else{b.left-=dm;if(b.left<=0){if(b.mafia){powerOutageOff('mafia');powerOutageOff('event')}else powerOutageOff('event');S.blk=null;log(powerIsOff()?'💡 เหตุไฟดับสิ้นสุด แต่ไฟยังดับจาก: '+powerOutageLabel():'💡 ไฟฟ้ากลับมาแล้ว ทำงานต่อได้')}}}
 if(S.evq&&S.evq.length&&!CUT.on&&!document.getElementById('evModal')){var q=S.evq.shift(),e=S.emp.find(function(x){return x.id==q.id});if(e)evPoach(e)}}
function evDraw(){var b=S.blk;if(!b||!b.on)return;var cv=$('cv'),g=cv.getContext('2d');g.fillStyle='rgba(4,6,18,.62)';g.fillRect(0,0,cv.width,cv.height);g.fillStyle='#ffd45a';g.font='bold 18px sans-serif';g.textAlign='center';g.fillText(b.mafia?'🔌 ถูกยากูซ่าตัดไฟ':'⚡ ไฟดับ',cv.width/2,28);g.textAlign='start'}
