function charIdOf(e){return CHAR_ASSETS[e.charId]?e.charId:(e.g?'mild-formal':'blue-suit-male')}
function portrait(e,size=56){const a=CHAR_IMAGES[charIdOf(e)];return '<img class="charPortrait" src="'+(a?a.portrait.src:'')+'" style="width:'+size+'px;height:'+Math.round(size*1.22)+'px;object-fit:cover;object-position:top" alt="">'}
function drawEmployee(g,e){
 // Selena (manager-white) never sits: she roams the office. While walking she uses the 4-frame walk cycle,
 // and when she pauses to inspect work she plays idle gesture frames (front row, indexes 4-6).
 // The three desk staff (Aki, Lucien, Ren) use the same seated/meeting rendering as every other employee.
 const custom=(e.charId==='manager-white'||e.charId==='security-guard')&&e.st!=='meeting';
 if(custom){
  const id=e.charId,working=e.st==='work';
  const moving=!!(e.path&&e.path.length)&&!(e.walkDelay>0);
  const idle=working&&!moving;
  const dir=idle?0:[0,2,1,3][e.d||0];
  const frame=idle?(id==='manager-white'?4+Math.floor(performance.now()/2600)%3:0):(Math.floor(e.f||0)%4);
  const im=CHAR_IMAGES[id].frames[dir][frame]||CHAR_IMAGES[id].frames[dir][0];
  if(im&&im.complete&&im.naturalWidth){
   const x=Math.round(e.x),y=Math.round(e.y);
   g.drawImage(im,0,0,64,80,x-20,y-51,40,50);
  }
  return;
 }

 const working=e.st==='work',meeting=e.st==='meeting';
 const id=charIdOf(e);
 const dir=meeting?([0,2,1,3][e.meetFace||0]):(working?0:[0,2,1,3][e.d||0]);
 const walkFrame=Math.floor((e.f||0))%4;
 const sitFrame=(working||meeting)?(Math.floor(performance.now()/520)%2):0;
 const frame=(working||meeting)?sitFrame:walkFrame;
 const im=CHAR_IMAGES[id].frames[dir][frame]||CHAR_IMAGES[id].frames[dir][0];
 if(im&&im.complete&&im.naturalWidth){
   const x=Math.round(e.x),y=Math.round(e.y);
   if(working||meeting){
     const bob=Math.round(Math.sin(performance.now()/(meeting?520:360))*1);
     g.drawImage(im,0,0,64,59,x-17,y-43+bob,34,37);
     if(working){
       g.fillStyle='#70452f';g.fillRect(x-20,y-10,40,6);
       g.fillStyle='#bd895a';g.fillRect(x-20,y-10,40,2);
       g.fillStyle='#2e3442';g.fillRect(x-7,y-15,14,3);
       g.fillStyle='rgba(255,255,255,.22)';g.fillRect(x-5,y-15,10,1);
     }else{
       // Small conference desk edge in front of the seated character.
       g.fillStyle='#65412f';g.fillRect(x-15,y-9,30,5);
       g.fillStyle='#b78355';g.fillRect(x-15,y-9,30,2);
       // A tiny speech mark gently pulses while the employee is in the meeting.
       if(Math.floor(performance.now()/650)%3!==2){
         g.fillStyle='#f5f1e8';g.fillRect(x+10,y-43,9,7);
         g.fillStyle='#46536a';g.fillRect(x+13,y-40,2,1);
         g.fillRect(x+16,y-40,2,1);
       }
     }
   }else{
     g.drawImage(im,x-19,y-49,38,52);
   }
 }else chs(g,e.x,e.y+10,e,e.d,e.f,0);
}

function drawKitchenWorker(g,e,t){
 const id=e.charId,imgs=CHAR_IMAGES[id];if(!imgs||e.state==='off')return;
 const isCook=id==='aunt-phen';
 const walking=['entering','leaving','leavingEdge','wandering'].includes(e.state);
 const dir=walking?([0,2,1,3][e.d||0]):0;
 const frame=walking?(Math.floor((e.anim||0))%4):
   (isCook&&e.state==='working'?(Math.floor(t*4)%4):0);
 const im=imgs.frames[dir][frame]||imgs.frames[dir][0];
 if(im&&im.complete&&im.naturalWidth){
   const x=Math.round(e.x),y=Math.round(e.y);
   const bob=walking?0:(isCook&&e.state==='working'?Math.round(Math.sin(t*5)*1):Math.round(Math.sin(t*1.8)*1));
   g.drawImage(im,x-19,y-49+bob,38,52);
   if(isCook&&e.state==='working'){
     g.fillStyle='#303746';g.fillRect(x-13,y-9,26,8);
     g.fillStyle='#687386';g.fillRect(x-11,y-8,22,5);
     g.fillStyle='#222833';g.fillRect(x-15,y-11,30,3);
     g.fillStyle='#d8dce4';g.fillRect(x+8,y-15,2,9);
     g.fillStyle='#9ca3af';g.fillRect(x+6,y-16,6,2);
     const phase=(t*3)%1;
     g.fillStyle='rgba(245,245,255,.78)';
     for(let i=0;i<3;i++){
       const sx=x-7+i*7+Math.sin(t*2+i)*2;
       const sy=y-21-((phase+i*.23)%1)*9;
       g.fillRect(Math.round(sx),Math.round(sy),2,3);
     }
     g.fillStyle='rgba(255,170,70,.20)';g.fillRect(x-9,y-3,18,3);
   }
 }
}

function migrateChars(){const all=[...(S.emp||[]),...(S.cands||[])];all.forEach(e=>{if(!CHAR_ASSETS[e.charId]&&e.charId!=='rei')e.charId=e.g?'mild-formal':'blue-suit-male';if(!e.role)e.role=KN[prim(e)]==='Programming'?'Programmer':KN[prim(e)]==='Creativity'?'Designer':'Coordinator';if(!e.ability)e.ability='ทำงานรอบคอบ';if(!e.personality)e.personality=PN[e.pe]||'ใจเย็น';if(e.special&&e.charId==='manager-white'){e.rank='mgr';e.sal=12000}});if(S&&S.salV!==2){all.forEach(e=>{try{e.sal=salf(e)}catch(_){}});S.salV=2}all.forEach(e=>{if(e.special&&['คุณเซเลน่า','คุณอากิ','คุณลูเซียน','คุณเรน'].indexOf(e.name)>=0)e.name=pick(FN)+' '+pick(LN);if(e.special){if(e.charId==='manager-white'){e.rank='mgr';e.sal=12000}else if(e.charId==='hr-glasses')e.sal=3500;else if(e.charId==='strategy-blond')e.sal=5000;else if(e.charId==='staff-red')e.sal=2800;else if(e.charId==='security-guard')e.sal=15000}})}

function mk(){const sk={};KS.forEach(k=>sk[k]=rnd(1,2));sk[pick(KS)]=rnd(3,5);const cid=pick(CHAR_POOL),gender=CHAR_ASSETS[cid].gender;const e={id:S.nid++,charId:cid,name:pick(FN)+' '+pick(LN),g:gender,role:pick(['Programmer','Designer','Marketing','Accountant','Coordinator']),personality:PN[rnd(0,4)],ability:pick(['ทำงานเร็วขึ้น 5%','ลดความเครียดได้ดี','โบนัสทักษะเฉพาะทาง','เพิ่มคุณภาพงาน']),hair:pick(['#222','#5a3a1a','#b5651d','#e0b050','#7a2a2a']),skin:pick(['#f1c9a5','#d9a066','#a8693a']),shirt:pick(['#e07a5f','#3d85c6','#81b29a','#f2cc8f','#9b72cf']),pe:rnd(0,4),sk,exp:0,hu:30,en:100,ha:75,sr:20,st:'home',x:0,y:0,path:[],d:0,f:0,tm:0,desk:0,bk:0,tr:0,cd:0};e.sal=salf(e);return e}

function clearKitchenRouteObstacles(){
 if(window.OFC&&OFC.floor)return;
 if(!Array.isArray(S.f))return;
 // Open a continuous aisle: remove the reception counter tile and the kitchen table tile
 // that occupy the only walkable route from the entrance to the kitchen.
 S.f=S.f.filter(f=>!((f.x===3&&f.y===11&&f.t==='counter')||
                     (f.x===8&&f.y===12&&f.t==='table')));
}

