function rollTonRequest(){
 const r=Math.random();
 const pool=r<.45?TON_REQUESTS.slice(0,3):r<.85?TON_REQUESTS.slice(3,6):TON_REQUESTS.slice(6);
 const j=pool[Math.floor(Math.random()*pool.length)];
 return {...j,need:{...j.need},reward:Math.min(2000,j.reward)};
}
