function customerRoll(){
 const W=[['mei',12],['phak',10],['ton',20],['praw',7],['pink',7],['tee',2],['goth',6],['bun',6],['coat',6],['leo',6],['fur',6],['teal',6],['chi',6],['brd',window.VIPX?VIPX.w('brd'):1],['sar',window.VIPX?VIPX.w('sar'):1],['shk',window.VIPX?VIPX.w('shk'):1],['emi',window.VIPX?VIPX.w('emi'):1],['hat',window.VIPX?VIPX.w('hat'):1]];
 try{BIZ.adjW(W)}catch(e){}
 try{window.OFC&&OFC.floor&&OFC.custW(W)}catch(e){}
 let n=Math.random()*W.reduce((a,b)=>a+b[1],0);
 for(const w of W){if((n-=w[1])<0)return w[0]}
 return 'mei';
}
function customerProject(c){
 const j=c.job;
 return {id:S.nid++,n:j.name,need:{...j.need},done:Object.fromEntries(Object.keys(j.need).map(k=>[k,0])),reward:c.type==='ton'?Math.min(2000,j.reward):j.reward,left:j.left,exp:j.exp,clientName:c.name,clientId:c.type};
}
function spawnCustomer(type){
 const d=CUSTOMER_DEFS[type],day=S.day,request=type==='ton'?rollTonRequest():d.job;
 const c={id:'visitor-'+day+'-'+type,type,name:d.name,role:d.role,kind:d.kind,portrait:CUSTOMER_PORTRAITS[type],shirt:d.shirt,hair:d.hair,skin:d.skin,speech:type==='ton'?request.speech:(window.VIPX&&VIPX.IDS.indexOf(type)>=0?VIPX.speech(type,d.speech):d.speech),job:{...request,need:{...request.need},reward:type==='ton'?Math.min(2000,request.reward):request.reward},x:OX.entXY()[0],y:OX.entXY()[1],d:2,f:0,anim:0,state:'entering',path:bfs(OX.ent()[0],OX.ent()[1],(x,y)=>x===OX.rw()[0]&&y===OX.rw()[1])||[],waitUntil:17*60,negotiated:0,showMore:0};
 S.customer.active=c;S.customer.lastSpawnDay=day;try{BIZ.onSpawn(c)}catch(e){}try{CAL.onSpawn(c)}catch(e){}
 if(!c.path.length){c.state='waiting';c.x=OX.rw()[0]*T+16;c.y=OX.rw()[1]*T+16;c.d=OX.rf()}
 log('🚪 '+c.name+' เดินทางมาติดต่อบริษัท');
}
function customerLeave(c,reason){
 if(!c||c.state==='leaving'||c.state==='leavingEdge'||c.state==='gone')return;
 c.state='leaving';c.path=pathToRoadEnd(c.x/T|0,c.y/T|0)||[];
 if(!c.path.length){c.state='leavingEdge';c.exitEdgeX=vw()*T+24}
 if($('clientModal'))$('clientModal').hidden=true;
 if(reason)log(reason);
}
function customerTick(dm,dr){
 if(!S.customer)S.customer={active:null,lastSpawnDay:0};
 const day=S.day,h=S.t/60;
 let c=S.customer.active;
 // Visitors walk from the road through the entrance and stop at Reception.
 if(c){
   if(c.state==='entering'){
     c.anim=(c.anim||0)+dr*10;
     if(mvE(c,dr)){c.state='waiting';c.x=OX.rw()[0]*T+16;c.y=OX.rw()[1]*T+16;c.d=OX.rf();c.f=0;toast(c.name+' มาถึงเคาน์เตอร์แล้ว');}
   }else if(c.state==='waiting'&&h>=17){
     customerLeave(c,c.name+' กลับแล้ว เนื่องจากหมดเวลาทำการ');
   }else if(c.state==='leaving'){
     c.anim=(c.anim||0)+dr*10;
     if(!c.path||!c.path.length){const [x,y]=tile(c);c.path=pathToRoadEnd(x,y)||[]}
     if(c.path.length&&mvE(c,dr)){c.state='leavingEdge';c.exitEdgeX=vw()*T+24}
     else if(!c.path.length){c.state='leavingEdge';c.exitEdgeX=vw()*T+24}
   }else if(c.state==='leavingEdge'){
     c.x=Math.min(c.exitEdgeX||vw()*T+24,c.x+32*dr);c.d=3;c.f=(c.f||0)+dr*7;
     if(c.x>=(c.exitEdgeX||vw()*T+24)){c.state='gone';S.customer.active=null;}
   }
 }
 // One regular customer round starts on day 5, then every 7 days.
 // Day 60 is month 2, day 30: it is reserved for Tee and suppresses all other visitors.
 const forced=day===60,mystery=day===MYS_DAY;
 const regular=day>=5&&(day-5)%7===0&&!forced&&!mystery;
 if((forced||mystery||regular)&&h>=(mystery?MYS_ARRIVE_H:forced?TEE_ARRIVE_H:9)&&!CUT.on&&S.customer.lastSpawnDay!==day){
   if(mystery){playMysteryCutscene(1)}else
   if(!S.customer.active||S.customer.active.state==='gone'){
     {const ty=forced?'tee':customerRoll();if(ty==='tee')playTeeCutscene(1);else spawnCustomer(ty)}
   }else{
     // Do not stack visitors at the Reception counter.
     S.customer.lastSpawnDay=day;
   }
 }
}
