function powerGridState(){
 if(!S.powerGrid){var legacyUtility=!!(S.utilities&&S.utilities.cut),legacyBlk=!!(S.blk&&S.blk.on);S.powerGrid={causes:{utility:legacyUtility,event:legacyBlk&&!S.blk.mafia,mafia:legacyBlk&&!!S.blk.mafia},backup:false,version:1};}
 if(!S.powerGrid.causes)S.powerGrid.causes={utility:false,event:false,mafia:false};
 ['utility','event','mafia'].forEach(function(k){if(typeof S.powerGrid.causes[k]!=='boolean')S.powerGrid.causes[k]=false});
 if(typeof S.powerGrid.backup!=='boolean')S.powerGrid.backup=false;
 return S.powerGrid;
}
function powerOutageOn(source){var g=powerGridState();if(!Object.prototype.hasOwnProperty.call(g.causes,source))source='event';g.causes[source]=true;if(source==='utility'&&S.utilities)S.utilities.cut=true;save(1);return g}
function powerOutageOff(source){var g=powerGridState();if(source==='all'){g.causes.utility=false;g.causes.event=false;g.causes.mafia=false;g.backup=false;}else if(Object.prototype.hasOwnProperty.call(g.causes,source))g.causes[source]=false;if(source==='utility'||source==='all'){if(S.utilities)S.utilities.cut=false;}if(!g.causes.event&&!g.causes.mafia)g.backup=false;return g}
function powerIsOff(){var g=powerGridState();return !!(g.causes.utility||g.causes.event||g.causes.mafia)}
function powerWorkMultiplier(){var g=powerGridState();if(!powerIsOff())return 1;if(g.backup&& (g.causes.event||g.causes.mafia))return .5;return 0}
