 if((!u.bill||u.bill.paid)&&S.day-u.lastBillDay>=7){var amount=Math.ceil((u.water+u.power)/10)*10;if(amount>0){u.bill={amount:amount,issued:S.day,due:S.day+2,paid:false};u.water=0;u.power=0;u.lastBillDay=S.day;log('🧾 บิลค่าน้ำค่าไฟออกแล้ว '+M(amount)+' · ครบกำหนดวันที่ '+u.bill.due)}}
