function clearPlayerInput(){K={};let sc=false;try{sc=!!CEOScene.dbg().st.active}catch(e){}if(window.JOY&&!sc){JOY.x=0;JOY.y=0}if(S&&S.pl)S.pl.mv=false;}   // ฉากนอกออฟฟิศ (คอนโด/ทางเดิน/ถนน/ทะเล) ใช้ค่าจอยเอง · ห้ามรีเซ็ตทุกเฟรมไม่งั้นค้างนิ้วบนจอยแล้วตัวละครไม่เดิน
function unstickPl(){const p=S.pl;if(!p||!pb(p.x,p.y))return;const cx=p.x/T|0,cy=p.y/T|0;let best=null,bd=1e9;
 for(let r=1;r<=14&&!best;r++)for(let yy=cy-r;yy<=cy+r;yy++)for(let xx=cx-r;xx<=cx+r;xx++){if(Math.max(Math.abs(xx-cx),Math.abs(yy-cy))!==r)continue;const px=xx*T+16,py=yy*T+16;if(pb(px,py))continue;const d=Math.hypot(px-p.x,py-p.y);if(d<bd){bd=d;best=[px,py]}}
 if(best){p.x=best[0];p.y=best[1];try{toast('🚶 ขยับ CEO ออกจากของที่เพิ่งวาง')}catch(e){}}}
function movePl(dr){const p=S.pl;if(playerMovementBlocked()){clearPlayerInput();return}if(window.OFC&&OFC.inAnim&&S.ofc&&OFC.inAnim()){OFC.anim(p,dr);return}try{if(window.OFC&&OFC.guard&&S.ofc)OFC.guard(p,!!(K.d||(window.JOY&&JOY.y>.35)))}catch(e){}unstickPl();let dx=(K.r?1:0)-(K.l?1:0),dy=(K.d?1:0)-(K.u?1:0),mg=1;if(!dx&&!dy&&window.JOY&&(JOY.x||JOY.y)){dx=JOY.x;dy=JOY.y;mg=Math.min(1,Math.hypot(dx,dy))}p.mv=!!(dx||dy);if(!dx&&!dy)return;const n=Math.hypot(dx,dy),s=130*dr*mg/n;const _px=!pb(p.x+dx*s,p.y),_py=!pb(p.x,p.y+dy*s);if(_px)p.x+=dx*s;if(_py)p.y+=dy*s;if(window.OFC&&OFC.slide&&S.ofc)OFC.slide(p,dx,dy,s,{x:_px,y:_py});p.f+=dr*8;p.d=Math.abs(dx)>=Math.abs(dy)?(dx<0?1:3):(dy<0?2:0);if((window.OFC&&OFC.exitHit&&S.ofc)?OFC.exitHit(p,!!(K.d||dy>.35)):((K.r||dx>.35)&&p.x>=15*T+10&&p.y>=14*T+2)){clearPlayerInput();CEOScene.tryOpen()}}
function kitchenWanderPath(e){
 // Chai wanders every room. The security guard only patrols the big hallway (rows 8-9) and the road outside the company; he never enters the work rooms.
 const guard=e.charId==='security-guard';
 const spots=(window.OFC&&OFC.floor&&S.ofc)?OFC.wander(guard):(guard?[[2,8],[4,8],[6,8],[8,8],[10,8],[12,8],[13,8],[2,9],[5,9],[8,9],[11,9],[13,9],[4,15],[7,15],[10,15],[13,15]]
   :[[3,3],[6,3],[9,3],[3,6],[6,6],[9,6],[5,8],[8,8],[12,8],[3,12],[7,12],[8,13]]);
 const [sx,sy]=tile(e);
 const choices=spots.filter(([x,y])=>x!==sx||y!==sy).sort(()=>Math.random()-.5);
 for(const [tx,ty] of choices){
   const path=bfs(sx,sy,(x,y)=>x===tx&&y===ty);
   if(path&&path.length)return path;
 }
 return [];
}
function kitchenWanderPath(e){
 const spots=(window.OFC&&OFC.floor&&S.ofc)?OFC.wander(e.charId==='security-guard'):[[3,3],[6,3],[9,3],[3,6],[6,6],[9,6],[5,8],[8,8],[12,8],[3,12],[7,12],[8,13]];
 const [sx,sy]=tile(e);
 const choices=spots.filter(([x,y])=>x!==sx||y!==sy).sort(()=>Math.random()-.5);
 for(const [tx,ty] of choices){
   const path=bfs(sx,sy,(x,y)=>x===tx&&y===ty);
   if(path&&path.length)return path;
 }
 return [];
}
function kitchenMove(e,dr){
 const p=e.path;
 if(!p||!p.length)return 1;
 const [tx,ty]=p[0],cx=tx*T+16,cy=ty*T+16;
 const dx=cx-e.x,dy=cy-e.y,d=Math.hypot(dx,dy),step=32*dr;
 e.anim=(e.anim||0)+dr*6;
 if(d<=step){e.x=cx;e.y=cy;p.shift();}
 else if(d>0){e.x+=dx/d*step;e.y+=dy/d*step;}
 if(Math.abs(dx)>Math.abs(dy))e.d=dx<0?1:3;
 else if(dy)e.d=dy<0?2:0;
 return !p.length;
}
function kitchenGoalOptions(e){
 if(window.OFC&&OFC.floor&&S.ofc)return OFC.kitchenGoals(e);
 // Candidate standing spots just inside the office. Furniture tiles (e.g. the sofa at 7,13) are skipped automatically.
 if(e.charId==='uncle-chai')return [[8,13],[8,12],[10,13],[7,12]];
 if(e.charId==='security-guard')return [[7,9],[5,9],[10,9],[8,8],[6,8],[4,9],[12,9],[3,9]];
 return [[9,13],[8,13],[10,13],[10,12]];
}
function kitchenFindEntry(e,roadX){
 for(const [gx,gy] of kitchenGoalOptions(e)){
   if(blk(gx,gy))continue;
   const rt=(window.OFC&&OFC.floor&&S.ofc)?OFC.roadTile(roadX):[roadX,15];const p=bfs(rt[0],rt[1],(x,y)=>x===gx&&y===gy);
   if(p&&p.length)return {goal:[gx,gy],path:p};
 }
 return null;
}
function kitchenEntry(e){
 // Use the same outside road and main entrance as ordinary employees.
 const roadX=e.charId==='uncle-chai'?4:e.charId==='security-guard'?6:5;
 {const rt=(window.OFC&&OFC.floor&&S.ofc)?OFC.roadTile(roadX):[roadX,15];e.x=rt[0]*T+16;e.y=rt[1]*T+16}e.d=2;e.anim=0;
 const r=kitchenFindEntry(e,roadX);
 if(r){e.kitchenGoal=r.goal;e.path=r.path;e.state='entering';}
 else{e.path=[];e.state='entryRetry';}
}
function updateKitchenStaff(dm,dr){
 if(!Array.isArray(S.kitchenStaff)||!S.kitchenStaff.length)return;
 const h=S.t/60;
 const employeesHome=Array.isArray(S.emp)&&S.emp.every(e=>e.st==='home');
 S.kitchenStaff.forEach(e=>{
   // Kitchen staff are not on duty before 08:30. This also corrects old saves
   // that may still have their state stored as 'working' from an earlier version.
   if(h<8.5){
     e.state='off';
     e.path=[];
     e.wanderWait=0;
     return;
   }

   if(!e.state)e.state='off';

   // Enter the office at the scheduled 08:30 start, including after loading a save.
   if(e.state==='off'&&h>=8.5&&h<19)kitchenEntry(e);

   if(e.state==='entryRetry'&&h<19){
     const rx=e.charId==='uncle-chai'?4:e.charId==='security-guard'?6:5;
     {const rt=(window.OFC&&OFC.floor&&S.ofc)?OFC.roadTile(rx):[rx,15];e.x=rt[0]*T+16;e.y=rt[1]*T+16}
     const r=kitchenFindEntry(e,rx);
     if(r){e.kitchenGoal=r.goal;e.path=r.path;e.state='entering';}
   }

   if(e.state==='entering'){
     if(kitchenMove(e,dr)){
       const goal=e.kitchenGoal||[8,13];
       e.x=goal[0]*T+16;e.y=goal[1]*T+16;
       e.state=(e.charId==='uncle-chai'||e.charId==='security-guard')?'wanderWait':'working';
       e.wanderWait=3;e.path=[];
     }
   }

   // Uncle Chai and the security guard patrol the office; Aunt Phen remains at the stove.
   if((e.charId==='uncle-chai'||e.charId==='security-guard')&&h<19&&['working','wanderWait','wandering'].includes(e.state)){
     if(e.state==='working')e.state='wanderWait';
     if(e.state==='wanderWait'){
       e.wanderWait=Math.max(0,(e.wanderWait||0)-dm);
       if(e.wanderWait<=0){
         e.path=kitchenWanderPath(e);
         if(e.path.length)e.state='wandering';
         else e.wanderWait=5;
       }
     }
     if(e.state==='wandering'){
       if(!e.path||!e.path.length){
         e.state='wanderWait';e.wanderWait=8;
       }else if(kitchenMove(e,dr)){
         e.state='wanderWait';e.wanderWait=8+Math.random()*12;
       }
     }
   }

   // Keep the original 19:00 departure rule: wait for all regular employees to be home.
   if(['working','wanderWait','wandering'].includes(e.state)&&h>=19&&employeesHome){
     const [x,y]=tile(e);
     e.path=pathToRoadEnd(x,y)||[];
     if(e.path.length)e.state='leaving';
   }
   if(e.state==='leaving'){
     if(!e.path||!e.path.length){
       const [x,y]=tile(e);e.path=pathToRoadEnd(x,y)||[];
       if(!e.path.length)return;
     }
     if(kitchenMove(e,dr)){
       e.state='leavingEdge';e.exitEdgeX=vw()*T+24;e.path=[];
     }
   }
   if(e.state==='leavingEdge'){
     const step=32*dr;
     e.x=Math.min(e.exitEdgeX||vw()*T+24,e.x+step);
     e.d=3;e.anim=(e.anim||0)+dr*6;
     if(e.x>=(e.exitEdgeX||vw()*T+24))e.state='off';
   }
 });
}

