// Dynamic outdoor sky visible through office windows. Images are embedded so the game
// remains a single offline HTML file. Each sky crossfades according to in-game time.
const SKY_ART = [
  'data:image/jpeg;base64,' + '',
  'data:image/jpeg;base64,' + '',
  'data:image/jpeg;base64,' + ''
];
const SKY_IMG = SKY_ART.map(src=>{const im=new Image();im.src=src;return im;});
const skySmooth = v=>{v=Math.max(0,Math.min(1,v));return v*v*(3-2*v)};
function skyWeights(hour){
  // Dawn 04:30-06:30, daytime, sunset 16:00-18:30, night 18:30-04:30.
  let day=0,sunset=0,night=0;
  if(hour>=6.5&&hour<16){day=1}
  else if(hour>=16&&hour<18.5){sunset=skySmooth((hour-16)/2.5);day=1-sunset}
  else if(hour>=18.5||hour<4.5){night=1}
  else if(hour>=4.5&&hour<6.5){day=skySmooth((hour-4.5)/2);night=1-day}
  return [day,sunset,night];
}
function drawWeatherWindow(g,px,py,hour,x,y){
  const weights=skyWeights(hour),t=performance.now()/1000;
  const sx=(t*5)%90,sy=210,sw=1536-sx,sh=654;
  g.save();
  g.beginPath();g.rect(px+2,py+15,28,14);g.clip();
  // Blend each painting with alpha; a short dissolve avoids abrupt weather changes.
  for(let i=0;i<3;i++){
    const im=SKY_IMG[i];if(!im.complete||!im.naturalWidth||weights[i]<=0)continue;
    g.globalAlpha=weights[i];
    g.drawImage(im,sx,sy,sw,sh,px+2,py+15,28,14);
  }
  g.globalAlpha=1;
  // Window mullions and a faint moving reflection.
  g.fillStyle='rgba(255,255,255,.30)';
  g.fillRect(px+15,py+15,1,14);
  g.fillRect(px+2,py+21,28,1);
  const glint=(Math.sin(t*.7+x*.8+y)*.5+.5)*.10;
  g.fillStyle='rgba(255,255,255,'+glint+')';
  g.fillRect(px+3+((t*2+x*3)%22),py+16,3,1);
  g.restore();
}

