function drawCustomer(g,c,t){
 if(!c||c.state==='gone')return;
 const walking=c.state==='entering'||c.state==='leaving'||c.state==='leavingEdge';
 const x=Math.round(c.x),y=Math.round(c.y);
 const atlas=CUSTOMER_SPRITE_IMAGES[c.type];
 // Same approach as drawCeo: 1:1 atlas cell, row by facing (c.d: 0 down,1 left,2 up,3 right), 4-frame walk cycle, idle = frame 0.
 const row=[0,2,1,3][c.d||0],frame=walking?Math.floor(c.f||0)%4:0;
 if(c.type!=='mystery'&&!NEW_CUSTOMERS.includes(c.type)){g.fillStyle='rgba(0,0,0,.32)';g.beginPath();g.ellipse(x,y+7,9,3,0,0,7);g.fill()}
 if(c.type==='mystery'){drawMysteryVisitor(g,c,walking,x,y)}else if(atlas&&atlas.complete&&atlas.naturalWidth){
   g.imageSmoothingEnabled=false;
   const cw=atlas.naturalWidth/4,ch=atlas.naturalHeight/4;
   if(cw>40){g.imageSmoothingEnabled=true;g.drawImage(atlas,frame*cw,row*ch,cw,ch,x-20,y-48,40,50);g.imageSmoothingEnabled=false}
   else g.drawImage(atlas,frame*32,row*44,32,44,x-16,y-34,32,44);
 }else{
   const d=CUSTOMER_DEFS[c.type],face=walking?([0,2,1,3][c.d||0]):2;
   const opts={id:200+({mei:1,tee:2,phak:3,ton:4}[c.type]||0),shirt:d.shirt,hair:d.hair,skin:d.skin,g:0};
   chs(g,c.x,c.y+10,opts,face,walking?(c.f||0):0,0);
 }
 if(c.state==='waiting'){
   const y2=c.y-48;
   g.fillStyle='rgba(12,16,26,.92)';g.fillRect(c.x-8,y2,16,13);
   g.fillStyle='#ffd45a';g.font='bold 12px sans-serif';g.fillText('!',c.x-2,y2+10);
 }
}

// ฤดูกาลละ 1 เดือน (30 วัน) เรียงตามไอคอน HUD จากซ้ายไปขวา: ใบไม้ผลิ → ร้อน → ใบไม้ร่วง → ฝน แล้ววนกลับใบไม้ผลิ
const SEASON_ORDER=['spring','summer','autumn','rainy'];
const SEASON_INFO={
 summer:{name:'ฤดูร้อน',icon:'☀️',desc:'อากาศร้อน แดดจัด ท้องฟ้าสดใส',color:'rgba(255,190,80,.045)'},
 rainy:{name:'ฤดูฝน',icon:'🌧️',desc:'เมฆครึ้ม ฝนตก พื้นถนนเปียกและมีแอ่งน้ำ',color:'rgba(80,130,190,.075)'},
 autumn:{name:'ฤดูใบไม้ร่วง',icon:'🍂',desc:'อากาศเย็นสบาย ลมพัด ใบไม้สีส้มร่วงปลิว',color:'rgba(190,125,55,.065)'},
 spring:{name:'ฤดูใบไม้ผลิ',icon:'🌸',desc:'อากาศอบอุ่น สดชื่น มีดอกไม้และกลีบดอกไม้ปลิว',color:'rgba(235,155,190,.055)'},
};
function currentSeason(){
 if(DEV_TEST_MODE&&DEV_TEST_SEASON)return DEV_TEST_SEASON;
 return SEASON_ORDER[Math.floor((Math.max(1,S.day)-1)/30)%SEASON_ORDER.length];
}
function drawSeasonEffects(g,w,h,t){
 const season=currentSeason(),info=SEASON_INFO[season];
 if(!info)return;
 // A subtle seasonal color grade over the scene.
 g.save();g.fillStyle=info.color;g.fillRect(0,0,w,H*T);
 if(['rainy','autumn','spring'].includes(season)){
   const now=performance.now()/1000;
   // อนุภาคสภาพอากาศแสดงเฉพาะพื้นที่กลางแจ้งและถนน
   for(let i=0;i<95;i++){
     const seed=i*97.13;
     const speed=season==='rainy'?175:season==='autumn'?42:30;
     const x=((seed*17+now*speed)%w+w)%w;
     const fallSpeed=season==='rainy'?330:season==='autumn'?75:48;
     const y=((seed*31+now*fallSpeed)%(H*T));
     const tx=Math.floor(x/T),ty=Math.floor(y/T);
     const tileChar=tl(tx,ty);
     if(tileChar!==','&&tileChar!==' ')continue;
     if(season==='rainy'){
       g.strokeStyle='rgba(185,215,255,.55)';g.lineWidth=1;
       g.beginPath();g.moveTo(x,y);g.lineTo(x-4,y+10);g.stroke();
     }else if(season==='autumn'){
       g.save();g.translate(Math.round(x),Math.round(y));g.rotate(Math.sin(now+i)*.8);
       g.fillStyle=['#d87932','#e6a33d','#a94f2d','#c98a35'][i%4];g.fillRect(-2,-3,4,7);g.fillRect(-1,-4,2,9);g.restore();
     }else{
       g.save();g.translate(Math.round(x),Math.round(y));g.rotate(Math.sin(now+i)*.5);
       g.fillStyle=['#f6b6d0','#fff0f5','#f2a1b9','#ffe0a8'][i%4];g.fillRect(-2,-2,4,4);g.fillRect(-1,-4,2,8);g.restore();
     }
   }
   if(season==='rainy'){g.fillStyle='rgba(40,65,100,.12)';g.fillRect(0,15*T,w,T)}
   if(season==='autumn'){g.fillStyle='rgba(155,90,35,.045)';g.fillRect(0,0,w,H*T)}
   if(season==='spring'){g.fillStyle='rgba(235,155,190,.025)';g.fillRect(0,0,w,H*T)}
 }
 g.restore();
}

