 const CLAUSE={
  none:{n:'ไม่มีเงื่อนไขพิเศษ',d:'ส่งตามกำหนด รับค่าตอบแทนเต็ม',m:1},
  rush:{n:'⚡ งานด่วน',d:'กำหนดส่งสั้นลง 30% แต่ค่าตอบแทน +25%',m:1.25},
  ontime:{n:'⏱ โบนัสส่งเร็ว',d:'ส่งก่อนกำหนดอย่างน้อย 1/3 ของเวลา รับโบนัส +20%',m:1},
  strict:{n:'🔒 สัญญาเข้มงวด',d:'ค่าตอบแทน +15% แต่ส่งไม่ทันโดนปรับหนักและเสียชื่อเสียงมาก',m:1.15}
 };
 const RIV0=[
  {id:'nova',n:'Nova Digital',ic:'🛰️',spec:'เทคโนโลยี',cash:120000,staff:18,rep:90,tr:0,aggr:.6,st:'grow',price:.9},
  {id:'bright',n:'BrightWorks Agency',ic:'📣',spec:'การตลาด / ดีไซน์',cash:60000,staff:9,rep:40,tr:0,aggr:.5,st:'flat',price:.82},
  {id:'pioneer',n:'Pioneer Consulting',ic:'🧭',spec:'ที่ปรึกษาธุรกิจ',cash:90000,staff:12,rep:60,tr:1,aggr:.3,st:'flat',price:.95}
 ];
 const ST={grow:['📈 กำลังเติบโต','#4ade80'],flat:['➖ ทรงตัว','#9fb0cc'],decline:['📉 ตกต่ำ','#fbbf24'],crisis:['⚠️ วิกฤตการเงิน','#f87171']};
 function st(){
  if(typeof S==='undefined'||!S)return null;
  let b=S.biz;if(!b||typeof b!=='object')b=S.biz={v:1};
  if(!b.cust||typeof b.cust!=='object')b.cust={};
  if(!Array.isArray(b.news))b.news=[];
  if(!b.stat||typeof b.stat!=='object')b.stat={won:0,lost:0,stolen:0,done:0,fail:0};
  if(!Array.isArray(b.rv)||!b.rv.length)b.rv=RIV0.map(r=>Object.assign({},r));
  if(typeof b.evNext!=='number')b.evNext=(S.day||1)+R(10,16);
  return b;
 }
 const rv=id=>st().rv.find(r=>r.id===id);
 function cust(id){const b=st();return b.cust[id]||(b.cust[id]={sat:60,jobs:0,fail:0,lost:0,seen:S.day})}
 const cname=id=>{try{return CUSTOMER_DEFS[id].name}catch(e){return id}};
 function news(t){const b=st();b.news.unshift({d:S.day,t});b.news.length=Math.min(b.news.length,14)}
 const ally=r=>!!r.ally, enemy=r=>r.tr<=-3&&!r.ally;
 const rivalPower=r=>r.rep+r.staff*2+r.cash/4000;
 /* ---------- 2.3 สัญญา ---------- */
 function terms(job,type){
  const b=st(),base=CMAP[type]||(job.reward>=3500?'corp':'general'),cu=type?b.cust[type]:null;
  let cls=base;if(cu&&(base==='general'||base==='niche')&&cu.jobs>=3&&cu.sat>=60)cls='regular';
  const K=CLS[cls],clause=K.pool[R(0,K.pool.length-1)];
  const units=Object.values(job.need||{}).reduce((a,v)=>a+v,0);
  const diff=clp(Math.round(1+units/200+(clause==='rush'?1:0)+(cls==='vip'?1:0)),1,5);
  return {cls,clause,diff,pen:Math.max(K.pen,clause==='strict'?.25:0),min:[1,1,2,2,3,4][diff]};
 }
 function onSpawn(c){
  try{
   const b=st();if(!b)return;const t=terms(c.job,c.type);c.biz=t;
   const base=CMAP[c.type];
   if(S.day>=8&&(base==='general'||base==='niche'||base==='corp')&&c.type!=='tee'){
    const cu=cust(c.type);let best=null,mx=0;
    b.rv.forEach(r=>{if(ally(r)||r.st==='crisis')return;const p=(.10+.30*r.aggr)*(r.tr<=-2?1.3:1)*(cu.sat<50?1.5:1)*(S.rep>r.rep*2?.5:1)*(b.war>S.day?1.5:1);if(Math.random()<p&&p>mx){mx=p;best=r}});
    if(best)c.rival={id:best.id,mul:clp(best.price-.02*R(0,3),.7,.95)};
   }
  }catch(e){console.error('[BIZ.onSpawn]',e)}
 }
 function bid(c){
  if(!c.rival||c.rivalDone)return false;
  const r=rv(c.rival.id);if(!r){c.rivalDone=1;return false}
  c.rivalDone=1;const cu=cust(c.type),reward=c.job.reward,price=r50(reward*c.rival.mul);
  const ch=clp(.30+(S.rep-r.rep)/400+(cu.sat-50)/200+(cu.jobs>=3?.1:0),.1,.85);
  const m=document.getElementById('clientModal');if(m)m.hidden=true;
  evAsk('⚔️ คู่แข่งเสนอราคา','<b>'+esc(c.name)+'</b> กำลังเทียบราคากับ <b>'+esc(r.ic+' '+r.n)+'</b> ที่เสนอ <b>'+M(price)+'</b> (ราคางานของเรา '+M(reward)+')<br><small>ความพึงพอใจของลูกค้า '+Math.round(cu.sat)+'/100 · ชื่อเสียงเรา '+Math.round(S.rep)+' · ชื่อเสียงคู่แข่ง '+Math.round(r.rep)+'</small>',[
   {label:'💰 ลดราคาเหลือ '+M(price)+'<br><small>ชนะแน่นอน แต่กำไรลดลง</small>',fn:function(){c.priceMul=c.rival.mul;stat('won');news('คุณลดราคาชนะ '+r.n+' ได้งานจาก '+c.name);setTimeout(function(){A.clientAccept()},30)}},
   {label:'🏆 ยืนราคาเดิม (โอกาสชนะ '+Math.round(ch*100)+'%)<br><small>ใช้ชื่อเสียงและความสัมพันธ์สู้ ถ้าแพ้ลูกค้าไปหาคู่แข่ง</small>',fn:function(){if(Math.random()<ch){stat('won');news('คุณชนะ '+r.n+' ด้วยชื่อเสียง ได้งานจาก '+c.name);cu.sat=clp(cu.sat+4,0,100);log('🏆 '+c.name+' เลือกเราเพราะชื่อเสียง');setTimeout(function(){A.clientAccept()},30)}else loseTo(c,r,'🏳️ '+c.name+' ไปใช้บริการ '+r.n)}},
   {label:'👋 ปล่อยให้คู่แข่งไป',fn:function(){loseTo(c,r,'👋 ปล่อยงาน '+c.name+' ให้ '+r.n)}}]);
  return true;
 }
 function stat(k){const b=st();b.stat[k]=(b.stat[k]||0)+1}
 function loseTo(c,r,msg){
  stat('lost');r.cash+=Math.round(c.job.reward*.6);r.rep+=1;cust(c.type).sat=clp(cust(c.type).sat-5,0,100);
  news(r.n+' คว้างานจาก '+c.name+' ไปได้');customerLeave(c,msg);
 }
 function sign(p,c){
  const b=st();if(!b||p.ct)return;
  const type=c&&c.type||null,t=(c&&c.biz)||terms(p,type);
  p.reward=r50(p.reward*CLAUSE[t.clause].m*((c&&c.priceMul)||1));
  if(t.clause==='rush')p.left=Math.max(2,Math.round(p.left*.7));
  let tight=0;if(S.emp.length<t.min){p.left=Math.max(2,p.left-1);tight=1}
  p.left0=p.left;
  p.ct={cls:t.cls,diff:t.diff,clause:t.clause,pen:t.pen,min:t.min,left0:p.left,signed:S.day,client:c?c.name:'ตลาดงาน',cid:type,tight};
  log('📑 สัญญา '+CLS[t.cls].n+' · '+CLAUSE[t.clause].n+' · ความเสี่ยง '+'★'.repeat(t.diff)+(tight?' · ทีมน้อยกว่าที่ควรมี กำหนดส่งแน่นขึ้น':''));
 }
 function done(p){
  let m=0,x=1,r=0;const b=st(),ct=p.ct;
  if(!b)return{m:0,x:1,r:0};
  b.stat.done++;
  const early=!!ct&&p.left>=Math.ceil(ct.left0/3);
  if(ct){if(ct.clause==='ontime'&&early){m=r50(p.reward*.2);log('⏱ ส่งงานก่อนกำหนด โบนัส '+M(m))}r=CLS[ct.cls].rep}
  const cu=ct&&ct.cid?cust(ct.cid):null;
  if(cu){
   x=cu.sat<40?.85:cu.sat>=85?1.05:1;
   if(x<1)log('😒 ลูกค้าไม่ค่อยพอใจ ค่าตอบแทนถูกลด 15%');else if(x>1)log('😊 ลูกค้าประทับใจ ค่าตอบแทน +5%');
   cu.sat=clp(cu.sat+8+(early?6:0),0,100);cu.jobs++;cu.lost=0;
   try{if(window.VIPX&&CMAP[ct.cid]==='vip')VIPX.gain(ct.cid,3)}catch(e){}
   if(cu.sat>=75&&Math.random()<.35&&S.board&&S.board.length<9){const g=gen();g.reward=r50(g.reward*1.2);g.n='🤝 แนะนำโดย '+cname(ct.cid)+': '+g.n;S.board.push(g);news(cname(ct.cid)+' แนะนำลูกค้าใหม่ให้เรา');toast('🤝 '+cname(ct.cid)+' แนะนำงานใหม่ ดูที่บอร์ดงาน')}
  }
  return{m,x,r};
 }
 function fail(p){
  const b=st(),ct=p.ct;if(!b)return 0;b.stat.fail++;
  let extra=0;
  if(ct){
   extra=Math.max(0,Math.round(p.reward*(ct.pen-.1)));
   if(ct.clause==='strict'||ct.cls==='vip')S.rep=Math.max(0,S.rep-5);
   const cu=ct.cid?cust(ct.cid):null;
   if(cu){cu.sat=clp(cu.sat-25,0,100);cu.fail++;
    try{if(window.VIPX&&CMAP[ct.cid]==='vip')VIPX.gain(ct.cid,-10)}catch(e){}
    if(cu.sat<25){cu.lost=S.day+R(15,30);const r=pickRival();if(r){r.cash+=Math.round(p.reward*.6);r.rep+=2}news(cname(ct.cid)+' หมดความไว้วางใจ ย้ายไปใช้คู่แข่ง'+(r?' ('+r.n+')':''));log('💔 '+cname(ct.cid)+' ย้ายไปใช้บริการคู่แข่ง')}}
  }
  if(extra)log('📑 ผิดสัญญา ถูกปรับเพิ่ม '+M(extra));
  return extra;
 }
 function drop(p){const ct=p.ct;if(!ct||!ct.cid)return;const cu=cust(ct.cid);cu.sat=clp(cu.sat-12,0,100);news('คุณยกเลิกสัญญากับ '+cname(ct.cid))}
 const pickRival=()=>{const a=st().rv.filter(r=>!ally(r));return a.length?a[R(0,a.length-1)]:null};
 function adjW(W){
  const b=st();if(!b)return;
  W.forEach(w=>{const cu=b.cust[w[0]];if(!cu)return;if(cu.lost>S.day)w[1]=0;else if(cu.sat>=70)w[1]*=1.5;else if(cu.sat<35)w[1]*=.5});
  if(!W.some(w=>w[1]>0))W[0][1]=1;
 }
 /* ---------- 2.2 ความพึงพอใจรายวัน ---------- */
 function factors(){
  const hasMgr=S.emp.some(e=>e.rank==='mgr'),avgHa=S.emp.length?S.emp.reduce((a,e)=>a+e.ha,0)/S.emp.length:50;
  return{hasMgr,avgHa,rep:S.rep||0,n:S.emp.length};
 }
 function satDaily(){
  const b=st(),F=factors();
  S.projects.slice().forEach(p=>{
   const ct=p.ct;if(!ct||!ct.cid)return;const cu=cust(ct.cid);
   const total=Object.values(p.need).reduce((a,v)=>a+v,0)||1,dn=Object.keys(p.need).reduce((a,k)=>a+Math.min(p.done[k]||0,p.need[k]),0),prog=dn/total;
   const plan=clp(1-p.left/Math.max(1,ct.left0),0,1);
   let d=prog>=plan-.05?2:-2;
   if(F.hasMgr)d+=1;if(F.avgHa<40)d-=1;else if(F.avgHa>=70)d+=1;
   const ks=Object.keys(p.need),sk=S.emp.length?ks.reduce((a,k)=>a+S.emp.reduce((s,e)=>s+(e.sk[k]||0),0)/S.emp.length,0)/ks.length:0;
   if(sk>=6)d+=1;else if(sk<3)d-=1;
   if(S.emp.length<ct.min)d-=1;
   if(F.rep>=300)d+=1;
   cu.sat=clp(cu.sat+d*.5,0,100);
   if(cu.sat<30&&prog<.5&&Math.random()<.12){
    S.projects=S.projects.filter(x=>x!==p);S.rep=Math.max(0,S.rep-2);cu.sat=clp(cu.sat-10,0,100);cu.lost=S.day+R(10,20);
    const r=pickRival();if(r){r.cash+=Math.round(p.reward*.5);r.rep+=1}
    news(cname(ct.cid)+' ยกเลิกสัญญา "'+p.n+'" เพราะไม่พอใจ'+(r?' ย้ายไป '+r.n:''));log('📑 '+cname(ct.cid)+' ยกเลิกสัญญา '+p.n);
   }
  });
  // ลูกค้าที่ไม่มีงานค้าง: ค่อยๆ ดีดกลับสู่ 60
  Object.keys(b.cust).forEach(id=>{const cu=b.cust[id];if(S.projects.some(p=>p.ct&&p.ct.cid===id))return;if(cu.sat<60)cu.sat=Math.min(60,cu.sat+.4);else if(cu.sat>60)cu.sat=Math.max(60,cu.sat-.15)});
 }
 /* ---------- 3. คู่แข่ง ---------- */
 function rivalSim(){
  const b=st();
  b.rv.forEach(r=>{
   r.cash+=Math.round(r.staff*R(30,55)*(r.st==='crisis'?.5:1)-r.staff*38);
   r.rep=Math.max(0,r.rep+(r.st==='grow'?.6:r.st==='flat'?.2:-.5)*(.5+Math.random()));
   if(r.tr>3)r.tr=3;if(r.tr<-5)r.tr=-5;
   if(S.rep>r.rep*1.4&&!ally(r))r.aggr=Math.min(.9,r.aggr+.01);
   if((S.day+r.id.length)%10===0){
    const old=r.st;
    if(r.cash<8000)r.st='crisis';
    else if(r.cash>140000&&r.staff<45){r.staff+=R(2,4);r.cash-=40000;r.st='grow';news(r.n+' เปิดสาขาใหม่ ขยายทีมเป็น '+r.staff+' คน');toast('🏢 '+r.n+' เปิดสาขาใหม่')}
    else if(r.rep<S.rep*.5)r.st='decline';
    else r.st=r.cash>70000?'grow':'flat';
    if(r.st==='crisis'&&old!=='crisis'){r.staff=Math.max(4,r.staff-R(1,3));news(r.n+' ประสบปัญหาการเงิน ลดพนักงาน')}
    if(r.st==='crisis'&&r.cash<2000)r.cash+=15000;   // ไม่ให้ล้มละลายถาวร: นักลงทุนอัดฉีด
   }
   if(ally(r)&&S.rep>r.rep*1.8){r.ally=0;r.tr=-2;news(r.n+' ยกเลิกพันธมิตร รู้สึกว่าบริษัทคุณใหญ่เกินไป')}
  });
  // แย่งงานบนบอร์ด
  b.rv.forEach(r=>{
   if(ally(r)||S.board.length<3)return;
   const p=(.10+.12*r.aggr)*(r.st==='crisis'?.3:1)*(b.war>S.day?2:1)*(r.tr<=-3?1.4:1);
   if(Math.random()<p){const j=S.board.splice(R(0,S.board.length-1),1)[0];r.cash+=Math.round(j.reward*.7);stat('stolen');news('⚔️ '+r.n+' คว้างาน "'+j.n+'" ไปก่อน');log('⚔️ '+r.n+' แย่งงาน "'+j.n+'" ไปแล้ว')}
  });
  // พันธมิตรส่งงานต่อ
  b.rv.forEach(r=>{if(ally(r)&&Math.random()<.12&&S.board.length<9){const g=gen();g.reward=r50(g.reward*1.1);g.n='🤝 จาก '+r.n+': '+g.n;S.board.push(g);news(r.n+' ส่งต่องานให้เรา');log('🤝 '+r.n+' ส่งงานต่อให้คุณ')}});
 }
 function events(){
  const b=st();if(S.day<15||S.day<b.evNext||document.getElementById('evModal'))return;
  b.evNext=S.day+R(9,16);
  const cr=b.rv.filter(r=>r.st==='crisis'&&!ally(r)),al=b.rv.filter(r=>!ally(r)&&r.tr>=1&&(S.rep||0)>=60);
  const opts=[];if(cr.length)opts.push('crisis');if(al.length)opts.push('ally');opts.push('war','expand');
  const k=opts[R(0,opts.length-1)];
  if(k==='crisis'){
   const r=cr[R(0,cr.length-1)];
   evAsk('🆘 '+esc(r.n)+' กำลังวิกฤต','คู่แข่งขาดสภาพคล่องและขอความช่วยเหลือ หรือคุณจะฉวยโอกาสนี้ก็ได้',[
    {label:'🤝 ให้ยืมเงิน '+M(15000)+'<br><small>ความสัมพันธ์ดีขึ้น เปิดทางเป็นพันธมิตร</small>',fn:function(){if(!pay(15000,'eq'))return false;r.cash+=15000;r.st='flat';r.tr=Math.min(3,r.tr+2);news('คุณช่วยเหลือ '+r.n+' ผ่านวิกฤต')}},
    {label:'🏴 รับลูกค้าและทีมงานของเขา<br><small>ได้งานรายใหญ่ 1 งาน +3 ชื่อเสียง แต่กลายเป็นศัตรู</small>',fn:function(){r.tr=Math.max(-5,r.tr-3);r.aggr=Math.min(.9,r.aggr+.15);r.staff=Math.max(3,r.staff-3);S.rep+=3;const g=gen();g.reward=r50(g.reward*1.3);g.n='🏴 ลูกค้าจาก '+r.n+': '+g.n;S.board.push(g);news('คุณฉวยโอกาสรับลูกค้าของ '+r.n);log('🏴 รับลูกค้าของ '+r.n+' (ศัตรูเพิ่ม)')}},
    {label:'👋 ไม่ยุ่ง',fn:function(){}}]);
  }else if(k==='ally'){
   const r=al[R(0,al.length-1)];
   evAsk('🤝 '+esc(r.n)+' เสนอร่วมมือ','เสนอเป็นพันธมิตร ส่งต่องานให้กันและไม่แย่งงานกัน ค่าธรรมเนียมแรกเข้า '+M(5000)+'<br><small>เงื่อนไข: ถ้าบริษัทคุณใหญ่กว่าเขา 1.8 เท่า พันธมิตรอาจเลิกสัญญา</small>',[
    {label:'✍️ ตกลง จ่าย '+M(5000),fn:function(){if(!pay(5000,'eq'))return false;r.ally=1;r.tr=3;S.rep+=3;news('คุณจับมือเป็นพันธมิตรกับ '+r.n)}},
    {label:'🙅 ปฏิเสธ',fn:function(){r.tr-=1;news('คุณปฏิเสธข้อเสนอของ '+r.n)}}]);
  }else if(k==='war'){
   const r=b.rv[R(0,b.rv.length-1)];if(ally(r))return;
   b.war=S.day+10;news(r.n+' ประกาศสงครามราคา ตลาดเดือด 10 วัน');
   evAsk('💥 สงครามราคา!',esc(r.n)+' ลดราคาทั้งตลาด 10 วัน คู่แข่งจะแย่งงานและลูกค้าถี่ขึ้น',[
    {label:'💪 ยืนหยัดด้วยคุณภาพ',fn:function(){S.rep+=1}},
    {label:'📢 ทุ่มโฆษณา '+M(3000)+'<br><small>ชื่อเสียง +4</small>',fn:function(){if(!pay(3000,'eq'))return false;S.rep+=4}}]);
  }else{
   const r=b.rv[R(0,b.rv.length-1)];r.aggr=Math.min(.9,r.aggr+.1);r.rep+=6;news(r.n+' คว้ารางวัลธุรกิจ แข่งขันหนักขึ้น');toast('🏆 '+r.n+' ได้รับรางวัลธุรกิจ')
  }
 }
 function daily(){
  const b=st();if(!b||S.day<8)return;
  satDaily();rivalSim();events();
 }
 /* ---------- UI ---------- */
 const bar=(v,c)=>'<i class="b"><u style="width:'+clp(v,0,100)+'%;background:'+c+'"></u></i>';
 const satC=v=>v>=70?'#4ade80':v>=40?'#fbbf24':'#f87171';
 function tag(p){
  const ct=p.ct;if(!ct)return '';
  return '<br><small>'+CLS[ct.cls].ic+' '+CLS[ct.cls].n+' · ความเสี่ยง '+'★'.repeat(ct.diff)+' · '+CLAUSE[ct.clause].n+' · ปรับ '+Math.round(ct.pen*100)+'% · ควรมีทีม '+ct.min+'+ คน</small>';
 }
 function modalHook(){
  const c=S.customer&&S.customer.active,m=document.getElementById('clientModal');if(!c||!c.biz||!m)return;
  const sp=m.querySelector('.clientSpeech');if(!sp||m.querySelector('.bizBox'))return;
  const t=c.biz,cu=cust(c.type),K=CLS[t.cls],cl=CLAUSE[t.clause],rw=r50(c.job.reward*cl.m);
  let h='<div class="bizBox" style="margin:8px 0;padding:8px 10px;border:1px solid #c89d4b;border-radius:8px;background:rgba(200,157,75,.12);font-size:12px;line-height:1.5">📑 <b>สัญญา</b> · '+K.ic+' '+K.n+' · ความเสี่ยง '+'★'.repeat(t.diff)+'<br>'+cl.n+' — <small>'+cl.d+'</small><br>ค่าตอบแทน <b>'+M(rw)+'</b> · ปรับถ้าส่งไม่ทัน '+Math.round(t.pen*100)+'% · ควรมีทีม '+t.min+'+ คน<br>ความพึงพอใจของลูกค้า '+Math.round(cu.sat)+'/100'+(cu.jobs?' · เคยทำงานด้วย '+cu.jobs+' ครั้ง':'')+(c.rival?'<br>⚔️ <b>'+esc(rv(c.rival.id).n)+'</b> กำลังเสนอราคาแข่ง'+'':'')+'</div>';
  sp.insertAdjacentHTML('afterend',h);
 }
 function view(){
  const b=st(),F=factors();if(!b)return '';
  const sec=t=>'<div class="c" style="background:#1b2740;border-color:#c89d4b"><b>'+t+'</b></div>';
  let h='';
  // ภาพรวมตลาด
  const tot=(S.rep||0)+10+b.rv.reduce((a,r)=>a+r.rep,0);
  h+=sec('📊 ภาพรวมตลาด')+'<div class="c"><small>ส่วนแบ่งตลาด (ตามชื่อเสียง)</small><br>🏢 เรา '+Math.round(((S.rep||0)+10)/tot*100)+'%'+bar(((S.rep||0)+10)/tot*100,'#60a5fa')
   +b.rv.map(r=>r.ic+' '+esc(r.n)+' '+Math.round(r.rep/tot*100)+'%'+bar(r.rep/tot*100,ST[r.st][1])).join('')
   +'<small>ชนะแข่งราคา '+b.stat.won+' · แพ้ '+b.stat.lost+' · ถูกแย่งงาน '+b.stat.stolen+' · ส่งงานสำเร็จ '+b.stat.done+' · ผิดสัญญา '+b.stat.fail+'</small>'+(b.war>S.day?'<br><small style="color:#f87171">💥 สงครามราคา เหลืออีก '+(b.war-S.day)+' วัน</small>':'')+'</div>';
  // สัญญา
  h+=sec('📑 สัญญาที่กำลังทำ ('+S.projects.length+')');
  h+=S.projects.length?S.projects.map(p=>{const ct=p.ct;return '<div class="c"><b>'+esc(p.n)+'</b> · '+M(p.reward)+' · เหลือ '+p.left+' วันทำงาน'+(ct?'<br><small>'+esc(ct.client)+' · '+CLS[ct.cls].ic+' '+CLS[ct.cls].n+' · ความเสี่ยง '+'★'.repeat(ct.diff)+'</small><br><small>'+CLAUSE[ct.clause].n+' — '+CLAUSE[ct.clause].d+'</small><br><small>ปรับ '+Math.round(ct.pen*100)+'% ของมูลค่า ('+M(Math.round(p.reward*ct.pen))+') ถ้าส่งไม่ทัน · ควรมีทีม '+ct.min+'+ คน</small>':'<br><small>สัญญาเดิม (ปรับ 10%)</small>')+'</div>'}).join(''):'<div class="c"><small>ยังไม่มีสัญญา</small></div>';
  // ลูกค้า
  const ids=Object.keys(b.cust);
  h+=sec('👥 ลูกค้า ('+ids.length+')')+'<div class="c"><small>ปัจจัยตอนนี้: ผู้จัดการ '+(F.hasMgr?'✅ มี':'❌ ไม่มี')+' · ความสุขทีมเฉลี่ย '+Math.round(F.avgHa)+' · พนักงาน '+F.n+' · ชื่อเสียง '+Math.round(F.rep)+'<br>ความพึงพอใจขึ้นเมื่อ: ส่งงานตรงเวลา ทักษะทีมสูง มีผู้จัดการ ทีมมีความสุข · ลดลงเมื่อ: งานช้า ทีมน้อยกว่าที่ควร ส่งไม่ทัน</small></div>';
  h+=ids.length?ids.sort((a,c)=>b.cust[c].sat-b.cust[a].sat).map(id=>{const cu=b.cust[id],cls=(cu.jobs>=3&&cu.sat>=60&&(CMAP[id]==='general'||CMAP[id]==='niche'))?'regular':(CMAP[id]||'general');
   return '<div class="c"><b>'+esc(cname(id))+'</b> <small>'+CLS[cls].ic+' '+CLS[cls].n+' · งานที่ทำ '+cu.jobs+' · ผิดสัญญา '+cu.fail+'</small><br><small>พึงพอใจ '+Math.round(cu.sat)+'/100'+(cu.lost>S.day?' · <span style="color:#f87171">ไปใช้คู่แข่ง (กลับมาอีก ~'+(cu.lost-S.day)+' วัน)</span>':cu.sat>=70?' · 😊 อาจแนะนำลูกค้าใหม่':cu.sat<35?' · 😠 เสี่ยงยกเลิกสัญญา':'')+'</small>'+bar(cu.sat,satC(cu.sat))+'</div>'}).join(''):'<div class="c"><small>ยังไม่เคยรับงานจากลูกค้าคนใด</small></div>';
  // คู่แข่ง
  h+=sec('⚔️ บริษัทคู่แข่ง');
  h+=b.rv.map(r=>{const lv=(()=>{let l=1;LV.forEach((x,i)=>{if(r.rep>=x[1])l=i+1});return LV[l-1][0]})(),rel=ally(r)?'🤝 พันธมิตร':enemy(r)?'💢 ศัตรู':r.tr>=1?'🙂 เป็นมิตร':r.tr<=-1?'😠 ไม่ถูกกัน':'😐 เป็นกลาง';
   return '<div class="c"><b>'+r.ic+' '+esc(r.n)+'</b> <small>'+esc(r.spec)+' · '+lv+'</small><br><small style="color:'+ST[r.st][1]+'">'+ST[r.st][0]+'</small> · <small>'+rel+'</small><br><small>เงินทุน '+M(r.cash)+' · พนักงาน '+r.staff+' · ชื่อเสียง '+Math.round(r.rep)+' · ราคาตลาดประมาณ '+Math.round(r.price*100)+'%</small><br><small>ความดุเดือด</small>'+bar(r.aggr*100,'#f87171')+'</div>'}).join('');
  // ข่าว
  h+=sec('📰 ข่าววงการ')+(b.news.length?'<div class="c">'+b.news.slice(0,8).map(n=>'<small>วัน '+n.d+' · '+esc(n.t)+'</small>').join('<br>')+'</div>':'<div class="c"><small>ยังไม่มีข่าว</small></div>');
  return h;
 }
