 function card(c){
  const t=TIERS[c.tier],c0=cs(),own=!!c0.owned[c.id],sel=c0.sel===c.id,can=S.money>=eff(c);
  let btn;
  if(sel)btn='<button class="cxBtn on">✓ กำลังใช้งาน</button>';
  else if(c.auction&&!own)btn='<button class="cxBtn no">🔨 ได้จากงานประมูลเท่านั้น</button>';
  else if(own)btn='<button class="cxBtn use" onclick="CARX.use(\''+c.id+'\')">🔑 ใช้งานคันนี้</button>';
  else if(pend===c.id)btn='<button class="cxBtn cf" onclick="CARX.buy(\''+c.id+'\')">ยืนยันซื้อ '+fmt(eff(c))+' ?</button>';
  else btn='<button class="cxBtn'+(can?'':' no')+'" onclick="CARX.buy(\''+c.id+'\')">'+(can?'🛒 ซื้อรถคันนี้':'เงินไม่พอ')+'</button>';
  return '<div class="cxCard'+(sel?' sel':'')+'"><span class="rb" style="background:'+t.col+'">'+t.name+'</span><img class="ph" alt="" src="'+c.photo+'"><div class="bd"><h4>'+c.name+'</h4><div class="th">'+c.th+'</div><p>'+c.desc+'</p><div class="st"><span>⏱ เดินทางเร็วขึ้น '+Math.round(t.red*100)+'%</span>'+(c.tier>=3?'<span>📸 คนมุงถ่ายรูป</span>':'')+'<span>🅿️ จอดรอที่ถนนตลอด</span>'+tagX(c)+'</div><div class="pr">'+prHtml(c)+'</div>'+btn+'</div></div>';
 }
