 const LV=[[0,'คนแปลกหน้า'],[50,'คนรู้จัก'],[120,'ลูกค้าประจำ'],[220,'ลูกค้าคนสำคัญ'],[340,'เพื่อนสนิท'],[500,'วีไอพีประจำโชว์รูม']];
