  g.textAlign='center';g.fillStyle=own?'#7dffb0':'#ffe39b';g.font='bold 11px sans-serif';g.fillText('🔨 LOT '+lot+' · '+(own?'SOLD · ของคุณ':'ประมูล'),x,y+13);
  g.fillStyle='#cfe0ff';g.font='10px sans-serif';g.fillText(c.name,x,y+25);
