   g.strokeStyle=win?'rgba(61,220,132,.9)':'rgba(255,196,96,.85)';g.lineWidth=2;g.beginPath();g.ellipse(s.x,s.y-6,96,21,0,0,Math.PI*2);g.stroke();
   const w=s.id==='rimu'?168:186,h=w*c.dh/c.dw;
