  {const Vp=SHW.vip;if(Vp&&Math.hypot(st.x-Vp.x,st.y-Vp.y)<80)return '💎 กด E เพื่อคุยกับ'+CUSTOMER_DEFS[Vp.id].name+' (VIP · ♥ '+VIPX.aff(Vp.id)+'/'+VIPX.MAX+')'}
  if(E&&Math.hypot(st.x-E.x,st.y-E.y)<60)return '💬 กด E เพื่อคุยกับ'+CARBOSS.ASST+' (ผู้ช่วยผู้จัดการ)';
  const sc=SH_CARS.find(s=>Math.abs(st.x-s.x)<110&&Math.abs(st.y-s.y)<60);
