 function drawAqst(g,t){
  const dt=Math.min(.05,Math.max(0,(t-(AQW.ct||t))/1000));AQW.ct=t;
  g.fillStyle='#262a33';g.fillRect(0,0,W,H);
  if(AQ_ST.complete&&AQ_ST.naturalWidth)g.drawImage(AQ_ST,-53.3,0,1066.7,600);
  if(!AQW.ped){const ids=['mei','leo','goth','coat','chi','teal','fur','bun','praw','pink'].filter(id=>{try{return CUSTOMER_SPRITE_IMAGES[id]}catch(e){return false}});
   AQW.pid=ids;AQW.ped=[0,1,2,3].map(i=>({kind:'customer',id:ids[(i*3+2)%Math.max(1,ids.length)]||'mei',x:130+i*210,y:452+((i*13)%26),d:i%2?1:3,f:i,v:32+i*5,al:1,hold:0}))}
  AQW.tn-=dt;
  const objs=[];
  AQW.ped.forEach(a=>{
   if(a.hold>0){a.hold-=dt;a.al=0;if(a.hold<=0){a.x=AD.doorX;a.y=AD.doorY+10;a.d=0;a.al=0;a.back=1}}
   else if(a.go){const dx=AD.doorX-a.x;if(Math.abs(dx)<6){a.go=0;a.hold=7+Math.random()*8;a.al=0}else{a.d=dx>0?3:1;a.x+=Math.sign(dx)*a.v*dt;a.f+=dt*5;a.al=Math.min(1,Math.abs(dx)/40)}}
   else if(a.back){a.y+=22*dt;a.d=0;a.f+=dt*5;a.al=Math.min(1,a.al+dt*2);if(a.y>=a.y0b){a.back=0;a.d=Math.random()<.5?1:3}if(!a.y0b)a.y0b=460}
   else{a.x+=(a.d===3?1:-1)*a.v*dt;a.f+=dt*5;a.al=1;if(a.x>W+50)a.d=1;if(a.x<-50)a.d=3}
   if(a.back&&!a.y0b)a.y0b=460;
   objs.push({y:a.y,draw:()=>{if(a.al<=.02)return;g.save();g.globalAlpha=a.al;drawStreetNPC(g,a,t);g.restore()}})});
  if(AQW.tn<=0){AQW.tn=14+Math.random()*10;const c=AQW.ped.filter(a=>!a.go&&!a.hold&&!a.back&&a.x>120&&a.x<W-120);if(c.length&&!st.trans){const a=c[Math.floor(Math.random()*c.length)];a.go=1}}
  objs.push({y:BOOTH.aqst.y,draw:()=>drawBooth(g,'aqst',t)});
  if(!st.hidden)objs.push({y:st.y,draw:()=>drawCEO(g)});
  const tr=st.trans,near=Math.abs(st.x-AD.doorX)<120&&st.y<490||(tr&&tr.type==='aqIn');
  AQW.dk+=((near?1:0)-AQW.dk)*Math.min(1,dt*6);
  objs.sort((a,b)=>a.y-b.y);objs.forEach(o=>o.draw());
  if(AQW.dk>.02){const k=AQW.dk;const gr=g.createLinearGradient(0,330,0,424);gr.addColorStop(0,'rgba(120,210,255,'+(.22*k)+')');gr.addColorStop(1,'rgba(255,236,170,'+(.30*k)+')');g.fillStyle=gr;g.fillRect(AD.doorX-110,330,220,94)}
  const dl=sceneDaylight();if(dl<1){g.fillStyle='rgba(6,10,34,'+((1-dl)*.26).toFixed(3)+')';g.fillRect(0,0,W,H)}
 }
 function aqstLeave(side){
  if(st.place!=='aqst'||!transLock())return;
  st.trans={type:'aqstLeave',side,t:0};toast(side<0?'⬅ เดินกลับร้านสนุกเกอร์':'➡ เดินต่อไปร้าน CARD SHOP');
 }
 function aqInBegin(){if(st.place!=='aqst'||!transLock())return;st.trans={type:'aqIn',t:0,ph:0}}
 function aqOutBegin(){if(st.place!=='aqin'||!transLock())return;st.trans={type:'aqOut',t:0,ph:0}}
 function aqTrans(tr,dt){
  if(tr.type==='aqIn'){
   if(tr.ph===0){if(walkTo(AD.doorX,AD.doorY+4,130,dt)){tr.ph=1;tr.t=0}}
   else{const k=Math.min(1,tr.t/.95);st.y=AD.doorY+4-k*30;st.dir=2;st.moving=1;st.frame=(st.frame+dt*7)%4;setFade(Math.max(0,(k-.4)/.6));if(k>=1){st.moving=0;st.trans=null;enter('aqin',{from:'aqst'})}}
   return true}
  if(tr.type==='aqOut'){
   if(tr.ph===0){if(walkTo(AR.exitX,AR.exitY-6,130,dt)){tr.ph=1;tr.t=0}}
   else{const k=Math.min(1,tr.t/.8);st.y=AR.exitY-6+k*30;st.dir=0;st.moving=1;st.frame=(st.frame+dt*7)%4;setFade(k);if(k>=1){st.moving=0;st.trans=null;enter('aqst',{from:'aqin'})}}
   return true}
  if(tr.type==='aqstLeave'){
   st.x+=tr.side*135*dt;st.dir=tr.side<0?1:3;st.moving=1;st.frame=(st.frame+135*dt/CEO_STRIDE)%4;setFade(Math.min(1,Math.max(0,(tr.t-.1)/.6)));
   if(tr.t>=.8){st.moving=0;st.trans=null;if(tr.side<0)enter('snkst',{from:'aqst'});else enter('cardst',{from:'aqst'})}
   return true}
  return false;
 }
 // ----- ภายในอควาเรียม -----
 function aqInInit(from){
  const q=AQM();q.visits=(q.visits||0)+1;AQW.first=q.q1===0?1.8:0;AQW.shot=null;
  AQW.guide={kind:'staff',id:'aq-keeper',x:AQ_GD.x,y:AQ_GD.y,d:0,f:0,mark:1};
  const ids=(AQW.pid&&AQW.pid.length?AQW.pid:['mei','leo','goth','coat']).slice();
  AQW.pid=ids;AQW.vis=[0,1,2].map(i=>aqNewVis(AQ_WP[(i*4+1)%AQ_WP.length][0],AQ_WP[(i*4+1)%AQ_WP.length][1]));AQW.spawnT=9;
 }
 function aqNewVis(x,y){const ids=AQW.pid&&AQW.pid.length?AQW.pid:['mei'];const a={kind:'customer',id:ids[Math.floor(Math.random()*ids.length)],x,y,d:2,f:Math.random()*4,tg:null,wait:1+Math.random()*3,n:2+Math.floor(Math.random()*3),leave:0,v:30+Math.random()*10};return a}
 function aqVisStep(dt){
  AQW.spawnT-=dt;if(AQW.spawnT<=0){AQW.spawnT=14+Math.random()*12;if(AQW.vis.length<5)AQW.vis.push(aqNewVis(AR.exitX+(Math.random()*60-30),AR.exitY-6))}
  AQW.vis=AQW.vis.filter(a=>{
   if(a.wait>0){a.wait-=dt;a.moving=0;if(a.y>430)a.d=2;if(a.wait<=0&&!a.leave){if(a.n--<=0){a.leave=1;a.tg=[AR.exitX,AR.exitY]}else{a.tg=AQ_WP[Math.floor(Math.random()*AQ_WP.length)]}}return true}
   if(!a.tg){a.wait=1;return true}
   const dx=a.tg[0]-a.x,dy=a.tg[1]-a.y,d=Math.hypot(dx,dy);
   if(d<4){a.tg=null;a.wait=a.leave?0:3+Math.random()*4;a.moving=0;if(a.leave&&a.y>=AR.exitY-8)return false;return true}
   const sp=Math.min(d,a.v*dt),nx=a.x+dx/d*sp,ny=a.y+dy/d*sp;
   if(aqSolid(nx,ny,6)&&!a.leave){a.tg=null;a.wait=.5;return true}
   a.x=nx;a.y=ny;a.f+=dt*5;a.d=Math.abs(dx)>Math.abs(dy)*1.15?(dx<0?1:3):(dy<0?2:0);return true});
 }
 function aqFishPos(f,t){const T=AQ_TK[f.tk];let cx,cy;if(T.ell){cx=T.ell[0];cy=T.ell[1]}else{cx=T.x+T.w/2;cy=T.y+T.h*(f.cy||.5)}
  const u=t*f.s+f.ph;return{x:cx+f.ax*Math.sin(u),y:cy+f.ay*Math.sin(u*1.37+f.ph*1.7),d:Math.cos(u)>=0?1:-1}}
 function aqDrawFish(g,t){
  if(!(FSH.complete&&FSH.naturalWidth))return;
  const by={};AQ_FISH.forEach((f,i)=>{(by[f.tk]=by[f.tk]||[]).push([f,i])});
  Object.keys(by).forEach(k=>{
   const T=AQ_TK[k];g.save();g.beginPath();if(T.ell)g.ellipse(T.ell[0],T.ell[1],T.ell[2],T.ell[3],0,0,6.283);else g.rect(T.x,T.y,T.w,T.h);g.clip();
   by[k].forEach(([f,i])=>{const row=(FISH.find(x=>x.id===f.sp)||{row:0}).row,p=aqFishPos(f,t),fr=Math.floor(t/150+i)%4;
    g.save();g.translate(p.x,p.y);g.scale(p.d,1);g.globalAlpha=.96;g.drawImage(FSH,fr*120,row*100,120,100,-60*f.k,-50*f.k,120*f.k,100*f.k);g.restore()});
   g.fillStyle='rgba(30,120,255,.10)';if(T.ell){g.beginPath();g.ellipse(T.ell[0],T.ell[1],T.ell[2],T.ell[3],0,0,6.283);g.fill()}else g.fillRect(T.x,T.y,T.w,T.h);
   g.restore()});
 }
 function aqVisible(t){
  const b=camBox(),x0=st.camX+b.ox,x1=x0+b.vw,y0=st.camY+b.oy,y1=y0+b.vh,o={};
  AQ_FISH.forEach(f=>{const p=aqFishPos(f,t);if(p.x>x0+10&&p.x<x1-10&&p.y>y0+10&&p.y<y1-10)o[f.sp]=1});return o}
 function drawAqin(g,t){
  const dt=Math.min(.05,Math.max(0,(t-(AQW.ct||t))/1000));AQW.ct=t;AQW.t=t;
  g.fillStyle='#0d1830';g.fillRect(0,0,W,H);
  if(AQ_IN.complete&&AQ_IN.naturalWidth)g.drawImage(AQ_IN,-53.3,0,1066.7,600);
  aqDrawFish(g,t);
  if(!st.talk||!st.talk.boss)aqVisStep(dt);
  if(AQW.first>0&&!st.trans&&!st.talk){AQW.first-=dt;if(AQW.first<=0){AQW.first=0;guideTalk(true)}}
  const objs=[];
  AQW.vis.forEach(a=>objs.push({y:a.y,draw:()=>drawStreetNPC(g,a,t)}));
  if(AQW.guide){const G=AQW.guide;objs.push({y:G.y,draw:()=>{drawStreetNPC(g,G,t);const q=AQM();if(q.q1===0||q.q1===1&&AQ_Q1.every(s=>q.q1got[s])){g.fillStyle='#ffd45a';g.font='bold 20px sans-serif';g.textAlign='center';g.fillText('!',G.x,G.y-92+Math.sin(t*.006)*3)}}})}
  objs.push({y:BOOTH.aqin.y,draw:()=>drawBooth(g,'aqin',t)});
  if(!st.hidden)objs.push({y:st.y,draw:()=>drawCEO(g)});
  objs.sort((a,b)=>a.y-b.y);objs.forEach(o=>o.draw());
  // ถ่ายรูป
  const S0=AQW.shot;
  if(S0){S0.t+=dt;
   if(!S0.cap&&S0.t>.06){S0.cap=1;try{aqShotDone(S0)}catch(e){console.error('[aq shot]',e)}}
   const a=Math.max(0,1-S0.t/.55);if(a>0){g.fillStyle='rgba(255,255,255,'+a.toFixed(2)+')';g.fillRect(0,0,W,H)}
   if(S0.t>.6)AQW.shot=null;
  }
 }
 function aqinPrompt(){
  if(st.sleep||st.trans||st.mode!=='scene'||st.talk||AQW.shot)return '';
  const bp=boothPrompt();if(bp)return bp;
  const G=AQW.guide;if(G&&Math.hypot(st.x-G.x,st.y-G.y)<80)return '💬 กด E เพื่อคุยกับ คุณมารีน · ผู้ดูแลอควาเรียม (เควส · อัลบั้ม · สมุดปลา)';
  if(AQW.vis.some(a=>Math.hypot(st.x-a.x,st.y-a.y)<56))return '💬 กด E เพื่อคุยกับผู้เข้าชม';
  if(st.y>=574&&Math.abs(st.x-AR.exitX)<110)return '🚪 กด E หรือเดินลงเพื่อออกจากอควาเรียม';
  return '📸 กด E เพื่อถ่ายรูป · ให้ปลาอยู่ในกรอบภาพ (เดินเข้าใกล้ตู้)';
 }
 function aqHud(g){
  if(st.place!=='aqin'||st.sleep||st.mode!=='scene')return;
  const q=AQM();let t='';
  if(q.q1===1)t='📋 เควส: ถ่ายรูปปลา 4 ตัว  '+AQ_Q1.map(s=>(q.q1got[s]?'✔ ':'○ ')+aqName(s)).join('  ');
  else if(q.q2===1)t='📋 สะสมภาพปลาให้ครบ 8 สายพันธุ์  ('+AQ_SP.filter(s=>q.seen[s]).length+'/8)';
  if(!t)return;
  g.save();g.font='bold 13px sans-serif';const w=Math.min(W-40,g.measureText(t).width+24);g.fillStyle='rgba(16,24,39,.86)';g.fillRect(W/2-w/2,52,w,26);g.fillStyle='#d0a451';g.fillRect(W/2-w/2,52,w,2);g.textAlign='center';g.fillStyle='#ffe9a8';g.fillText(t,W/2,70);g.restore();
 }
 function aqShot(){
  if(AQW.shot||st.trans||st.talk)return;
  AQW.shot={t:0,cap:0,spec:aqVisible(AQW.t||performance.now())};
 }
 function aqShotDone(S0){
  const q=AQM(),c=cv();let full='',thumb='';
  try{full=c.toDataURL('image/jpeg',.9);const k=document.createElement('canvas');k.width=320;k.height=200;k.getContext('2d').drawImage(c,0,0,k.width,k.height);thumb=k.toDataURL('image/jpeg',.62)}catch(e){}
  const sp=Object.keys(S0.spec);q.photos=(q.photos||0)+1;
  const day=S.day;q.album.push({d:day,sp,img:thumb});if(q.album.length>8)q.album.shift();
  AQW.last=full;const fresh=[];
  sp.forEach(s=>{if(!q.seen[s]){q.seen[s]=1;fresh.push(s)}});
  let msg=sp.length?'📸 ถ่ายรูปแล้ว · พบ '+sp.map(aqName).join(', '):'📸 ถ่ายรูปแล้ว (ไม่มีปลาอยู่ในกรอบ)';
  if(q.q1===1){const nw=sp.filter(s=>AQ_Q1.includes(s)&&!q.q1got[s]);nw.forEach(s=>{q.q1got[s]=1});if(nw.length)msg+=' · เควส '+AQ_Q1.filter(s=>q.q1got[s]).length+'/4';
   if(AQ_Q1.every(s=>q.q1got[s]))setTimeout(()=>toast('✅ ถ่ายครบ 4 ตัวแล้ว! ไปรายงานคุณมารีน'),900)}
  if(q.q2===1&&AQ_SP.every(s=>q.seen[s]))setTimeout(()=>toast('🏆 ถ่ายครบ 8 สายพันธุ์แล้ว! ไปรับรางวัลที่คุณมารีน'),900);
  toast(msg);try{save(1)}catch(e){}
  aqxCss();let cd=document.getElementById('aqShotCard');if(!cd){cd=document.createElement('div');cd.id='aqShotCard';document.body.appendChild(cd)}
  cd.innerHTML='<img src="'+(full||thumb)+'" alt=""><button onclick="CEOScene.aq.save()">⬇ บันทึกรูป</button><button onclick="document.getElementById(\'aqShotCard\').remove()">ปิด ✕</button>';cd.hidden=false;
  clearTimeout(aqShotCard_t);aqShotCard_t=setTimeout(()=>{const x=document.getElementById('aqShotCard');if(x)x.remove()},9000);
 }
 let aqShotCard_t=0;
 function aqSavePhoto(){if(!AQW.last)return;const a=document.createElement('a');a.href=AQW.last;a.download='aquarium_day'+S.day+'_'+Date.now()+'.jpg';document.body.appendChild(a);a.click();a.remove()}
 // ----- เควสและบทสนทนา -----
 function aqXpGain(n){const b=fishLv();S.fx=(S.fx||0)+n;const a=fishLv();if(a>b)setTimeout(()=>toast('🎣 เลเวลตกปลาเพิ่มเป็น Lv'+a+'!'),600)}
 function guideTalk(first){
  const q=AQM();let tx='',btns='';
  if(q.q1===0){q.q1=1;tx='ยินดีต้อนรับสู่อควาเรียมค่ะ! ดิฉันมารีน ผู้ดูแลที่นี่ 🐋<br>ที่นี่จัดแสดงเฉพาะ <b>ฉลาม</b>และ<b>ปลาระดับ Mythic</b> ฝากช่วยภารกิจแรกหน่อยนะคะ: <b>ถ่ายรูปปลา 4 ตัว</b> ได้แก่ <b>'+AQ_Q1.map(aqName).join(' · ')+'</b> กดถ่ายรูปด้วย E ให้ปลาอยู่ในกรอบภาพ ถ้าทำได้จะมี <b>ค่าประสบการณ์ตกปลา</b>เป็นของขวัญค่ะ'}
  else if(q.q1===1){
   if(AQ_Q1.every(s=>q.q1got[s])){q.q1=2;q.q2=1;aqXpGain(10);S.money+=1000;try{S.today.inc+=1000}catch(e){}log('🐋 เควสอควาเรียมสำเร็จ! +ค่าประสบการณ์ตกปลา +$1,000');
    tx='เก่งมากค่ะ! ถ่ายครบทั้ง 4 ตัวเลย 🎉 รับ <b>ค่าประสบการณ์ตกปลา +10</b> และเงินรางวัล <b>'+M(1000)+'</b> ไปเลยค่ะ<br>เควสพิเศษต่อไป: <b>ถ่ายภาพปลาให้ครบทั้ง 8 สายพันธุ์</b> (ฉลามเสือ · ฉลามหัวค้อน · ฉลามขาว · ฉลามวาฬ · มังกรทอง · มังกรน้ำแข็ง · มังกรเพลิง · ตาราจักรวาล) รางวัลใหญ่รออยู่นะคะ'}
   else tx='ยังขาดอีก <b>'+AQ_Q1.filter(s=>!q.q1got[s]).map(aqName).join(', ')+'</b> ค่ะ ลองเดินเข้าใกล้ตู้แล้วกด E ตอนที่ปลาว่ายอยู่ในกรอบภาพนะคะ 📸'}
  else if(q.q2===1){
   if(AQ_SP.every(s=>q.seen[s])){q.q2=2;aqXpGain(25);S.money+=5000;try{S.today.inc+=5000}catch(e){}S.rep=(S.rep||0)+5;log('🏆 สะสมภาพปลาครบ 8 สายพันธุ์! +$5,000 +ค่าประสบการณ์ตกปลา +25');
    tx='สุดยอดเลยค่ะ! คุณถ่ายภาพได้ครบทั้ง 8 สายพันธุ์ 🏆 รับ <b>'+M(5000)+'</b> · <b>ค่าประสบการณ์ตกปลา +25</b> · <b>ชื่อเสียง +5</b> ค่ะ ขอบคุณที่ช่วยเป็นแขกคนสำคัญของอควาเรียมนะคะ'}
   else tx='ภาพที่สะสมได้แล้ว '+AQ_SP.filter(s=>q.seen[s]).length+'/8 สายพันธุ์ค่ะ ยังขาด: <b>'+AQ_SP.filter(s=>!q.seen[s]).map(aqName).join(', ')+'</b>'}
  else tx='ขอบคุณที่แวะมานะคะ 💙 ภาพปลาครบ 8 สายพันธุ์แล้ว ที่นี่เป็นเหมือนบ้านของคุณเลยค่ะ ถ่ายรูปเก็บความทรงจำต่อได้เลยนะคะ';
  try{save(1)}catch(e){}
  aqxOpen('<div class="aqP"><h3><span>🐋 คุณมารีน · ผู้ดูแลอควาเรียม</span><button class="btn" onclick="CEOScene.aq.xclose()">ปิด ✕</button></h3><div class="aqTx">'+tx+'</div><div class="aqAl" style="grid-template-columns:1fr 1fr"><button class="aqBtn" onclick="CEOScene.aq.album()">🖼️ อัลบั้มภาพ ('+q.album.length+')</button><button class="aqBtn" onclick="CEOScene.aq.dex()">📖 สมุดบันทึกปลา ('+AQ_SP.filter(s=>q.seen[s]).length+'/8)</button></div></div>');
 }
 function aqAlbum(){
  const q=AQM();
  aqxOpen('<div class="aqP"><h3><span>🖼️ อัลบั้มภาพอควาเรียม <small style="color:#9fb0cc">(ถ่ายแล้ว '+q.photos+' รูป · เก็บล่าสุด 8 รูป)</small></span><button class="btn" onclick="CEOScene.aq.xclose()">ปิด ✕</button></h3>'+(q.album.length?'<div class="aqAl">'+q.album.slice().reverse().map(a=>'<div><img src="'+a.img+'" alt="">วันที่ '+a.d+'<br>'+(a.sp.length?a.sp.map(aqName).join(', '):'ไม่มีปลา')+'</div>').join('')+'</div>':'<div class="aqTx">ยังไม่มีภาพถ่าย กด E ในอควาเรียมเพื่อถ่ายรูป</div>')+'<div style="margin-top:8px"><button class="aqBtn" onclick="CEOScene.aq.talk()">⬅ กลับ</button></div></div>');
 }
 function aqDex(){
  const q=AQM();
  aqxOpen('<div class="aqP"><h3><span>📖 สมุดบันทึกปลา</span><button class="btn" onclick="CEOScene.aq.xclose()">ปิด ✕</button></h3><div class="aqAl" style="grid-template-columns:repeat(2,1fr)">'+AQ_SP.map(s=>{const f=FISH.find(x=>x.id===s),ok=q.seen[s];return '<div style="text-align:left;'+(ok?'':'opacity:.55')+'">'+(ok?aqIcon(f,.5):'<div style="width:60px;height:50px;display:flex;align-items:center;justify-content:center;font-size:26px">❓</div>')+'<b>'+(ok?(f.myth?'✨ ':'')+f.n:'ยังไม่เคยถ่ายภาพ')+'</b><br>'+(ok?AQ_FACT[s]:'ถ่ายภาพให้ได้เพื่อปลดล็อก')+'</div>'}).join('')+'</div><div style="margin-top:8px"><button class="aqBtn" onclick="CEOScene.aq.talk()">⬅ กลับ</button></div></div>');
 }
 function visTalk(a){toast('🙂 ผู้เข้าชม: '+AQ_LINES[Math.floor(Math.random()*AQ_LINES.length)])}
 function aqInteract(){
  if(boothAt()){callOpen();return}
  if(st.place==='aqst'){
   if(Math.abs(st.x-AD.doorX)<95&&st.y<490){aqInBegin();return}
   toast('🐋 อควาเรียมอยู่ตรงหน้า · เดินไปที่ประตูกระจกตรงกลางแล้วกด E');return}
  const G=AQW.guide;if(G&&Math.hypot(st.x-G.x,st.y-G.y)<80){guideTalk();return}
  const v=AQW.vis.find(a=>Math.hypot(st.x-a.x,st.y-a.y)<56);if(v){visTalk(v);return}
  if(st.y>=574&&Math.abs(st.x-AR.exitX)<110){aqOutBegin();return}
  aqShot();
 }
