 function fmSolid(x,y){return (!(window.WZ_FARMER_AWAY&&WZ_FARMER_AWAY())&&Math.hypot(x-FM_NPC.x,(y-FM_NPC.y)*1.3)<20)||(Math.abs(x-FM_BD.x)<34&&Math.abs(y-FM_BD.y)<12)}
