     if(s>=3){const k=.5+.5*Math.sin(t*.006+i);g.fillStyle='rgba(255,240,150,'+(.35+.4*k).toFixed(2)+')';g.fillRect(pl.x-26+((t*.03+i*17)%52),pl.y-30-k*8,3,3);text(g,'🧺',pl.x,pl.y-FM_H/2-6-k*3,16,'#fff')}
     else if(!wet&&!rain){text(g,'💧',pl.x,pl.y-FM_H/2-4+Math.sin(t*.008+i)*2,15,'#fff')}
