 // เฟรมรถ: 0/1 = ล้อหมุนสลับ · 2 = ไฟหน้าเปิด
 function vehFrame(b,mv,lights){if(lights||b.carry||b.state==='depart')return 2;return mv?Math.floor(b.ph)%2:0}
 // รถที่ซื้อจอดรอที่ป้ายตลอดเวลา (ไม่ต้องรอรถเมล์)
 function parkCar(s){
  applyVehicle();if(!BUS.car)return;
  const x=busStopX(),w=busW();
  s.bus={x,v:0,state:'dwell',door:1,dwell:0,t:0,t0:1,ph:0,acc:0,carry:false,puff:0,car:true};s.wait=null;
  const T=streetState;if(T&&T.cars)T.cars=T.cars.filter(c=>!(c.lane===1&&carRr(c)<x+w+46&&carF(c)>x-46));
 }
 // ===== คนมุงถ่ายรูปรถ (Mythic ขึ้นไป) =====
 function crowdPool(){return STREET_NPC_POOL.filter(p=>(p.kind==='staff'||p.kind==='customer')&&p.id!=='mystery')}
 function crowdStep(dt){
  const s=st.s;if(!s)return;
  const K=s.crowd||(s.crowd={list:[],t:0,next:4+Math.random()*4,active:false,dur:0,flash:0});
  const c=window.CARX&&CARX.cur(),b=s.bus;
  const want=!!(c&&c.tier>=3&&b&&b.car&&b.state==='dwell'&&!b.carry&&s.phase==='free');
  K.t+=dt;
  if(want&&!K.active&&K.t>=K.next){
   K.active=true;K.t=0;K.dur=15+Math.random()*10;
   const n=4+Math.floor(Math.random()*3),pool=crowdPool(),w=busW(),dz=STOP.doorX;
   for(let i=0;i<n;i++){
    let x=b.x+w*(.08+.84*i/Math.max(1,n-1));if(Math.abs(x-dz)<44)x+=(x<dz?-1:1)*48;
    x=Math.max(30,Math.min(W-30,x));
    const sp=pool[Math.floor(Math.random()*pool.length)],fromL=x<W/2,sx=fromL?-40-i*40:W+40+i*40;
    K.list.push({kind:sp.kind,id:sp.id,x:sx,y:566,d:fromL?3:1,f:Math.random()*4,v:48,wait:0,tx:x,ty:552+Math.random()*30,st:'in',sh:.5+Math.random()*1.6,cam:0,fl:0,fx:0});
   }
  }
  if(K.active&&(K.t>K.dur||!want)){K.active=false;K.t=0;K.next=10+Math.random()*10;K.list.forEach(p=>{p.st='out'})}
  K.flash=Math.max(0,K.flash-dt*3.2);
  K.list.forEach(p=>{
   if(p.st==='in'){
    const dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy),sp=Math.min(d,48*dt);
    if(d<1.2){p.st='shoot';p.d=2;p.v=0}
    else{p.x+=dx/d*sp;p.y+=dy/d*sp;p.v=48;p.d=Math.abs(dx)>Math.abs(dy)?(dx<0?1:3):(dy<0?2:0);p.f+=dt*6}
   }else if(p.st==='shoot'){
    p.d=2;p.v=0;p.sh-=dt;
    if(p.sh<=0&&p.cam<=0){p.cam=.65;p.fl=0;p.sh=1+Math.random()*2.4}
    if(p.cam>0){p.cam-=dt;if(p.cam<=.18&&!p.fl){p.fl=1;p.fx=.22;K.flash=Math.min(1,K.flash+.5)}}
    if(p.fx>0)p.fx-=dt;
   }else{
    const dir=p.x<W/2?-1:1;p.x+=dir*62*dt;p.d=dir<0?1:3;p.v=62;p.f+=dt*7;p.cam=0;p.fx=0;
   }
  });
  K.list=K.list.filter(p=>p.x>-90&&p.x<W+90);
 }
 function crowdObjs(g,t){
  const K=st.s&&st.s.crowd;if(!K)return[];
  return K.list.map(p=>({y:p.y,draw:()=>{
   drawStreetNPC(g,p,t);
   if(p.cam>0){ // ยกมือถือขึ้นถ่าย
    const hx=p.x+(p.d===3?9:p.d===1?-9:6),hy=p.y-56-Math.min(6,p.cam*14);
    g.save();g.fillStyle='#10131c';g.fillRect(hx-3,hy-5,7,11);g.fillStyle='#8fd3ff';g.fillRect(hx-2,hy-4,5,9);
    if(p.fx>0){g.globalCompositeOperation='lighter';const gr=g.createRadialGradient(hx,hy,1,hx,hy,26);gr.addColorStop(0,'rgba(255,255,255,'+Math.min(1,p.fx*5).toFixed(2)+')');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(hx-28,hy-28,56,56);
     g.fillStyle='rgba(255,255,255,'+Math.min(1,p.fx*5).toFixed(2)+')';g.fillRect(hx-9,hy-1,18,2);g.fillRect(hx-1,hy-9,2,18)}
    g.restore();
   }
  }}));
 }
 function crowdFlash(g){
  const s=st.s,K=s&&s.crowd,b=s&&s.bus;if(!K||!b||!b.car||K.flash<=.02)return;
  const w=busW(),h=BUS.ch*BUS.s;
  g.save();g.globalCompositeOperation='lighter';g.fillStyle='rgba(255,255,255,'+(.22*K.flash).toFixed(3)+')';
  g.fillRect(b.x,BUS.base-h,w,h);g.restore();
 }
function drawStreet(g,t,preview=false){
  drawStreetBackground(g);
  if(preview)return;
  drawCompanyFront(g,t);
  drawBusBay(g,t);
  if(!streetState)streetInit();
  const ss=st.s,objs=[];
  ST_LAMP_X.forEach((x,i)=>objs.push({y:ST_LAMP_Y,draw:()=>streetLampPosts(g,i)}));
  streetState.npcs.forEach(a=>objs.push({y:a.y,draw:()=>{if(a.fadeA!=null){g.save();g.globalAlpha=Math.max(0,Math.min(1,a.fadeA));drawStreetNPC(g,a,t);g.restore()}else drawStreetNPC(g,a,t)}}));
  objs.push({y:STOP.signY,draw:()=>drawStopSign(g,t)});
  objs.push({y:STOP.benchY,draw:()=>drawBench(g)});
  objs.push({y:528,draw:()=>drawBeachSignpost(g,t)});
  if(st.kg&&st.place==='street')kidObjs(g,t).forEach(o=>objs.push(o));
  carObjs(g,t).forEach(o=>objs.push(o));
  try{crowdObjs(g,t).forEach(o=>objs.push(o))}catch(e){}
  try{if(window.YZ&&YZ.streetObjs)YZ.streetObjs(g,t).forEach(o=>objs.push(o))}catch(e){}
  try{if(window.RIM&&RIM.streetObjs)RIM.streetObjs(g,t).forEach(o=>objs.push(o))}catch(e){}
  try{if(window.REL&&REL.streetObjs)REL.streetObjs(g,t).forEach(o=>objs.push(o))}catch(e){}
  if(ss&&ss.bus)objs.push({y:BUS.base,draw:()=>drawBus(g,t)});
  if(!st.hidden)objs.push({y:st.y,draw:()=>{g.save();g.globalAlpha=ss&&ss.cAlpha!=null?Math.max(0,Math.min(1,ss.cAlpha)):1;drawCEO(g);g.restore()}});
  objs.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());
  try{crowdFlash(g)}catch(e){}
  drawStreetFx(g);
  streetAtmosphere(g,t); // v91: แสง/สีท้องฟ้า/ไฟถนน/ไฟอาคาร/หมอก ตามเวลาในเกม
  drawStreetGlow(g,t);
  try{if(window.GHOST&&GHOST.streetDraw)GHOST.streetDraw(g,t)}catch(e){}
 }

