 // วิวทะเล (ท้องฟ้า-ทะเล-ดวงอาทิตย์/ดวงจันทร์-เกาะ-เรือใบ-นก) ในกรอบ x0,y0,x1,y1 · เส้นขอบฟ้า hy
 function seaView(g,t,dw,x0,y0,x1,y1,hy){
  const w=x1-x0,h=y1-y0,hh=sceneHour();g.save();g.beginPath();g.rect(x0,y0,w,h);g.clip();
  const dusk=Math.max(0,1-Math.abs(dw-.5)*2.4)*.55;
  g.fillStyle=GRAD(g,0,y0,0,hy,[[0,mix('#0a1030','#3f9be8',dw)],[1,mix(mix('#262c64','#aee3ff',dw),'#ff9a5c',dusk)]]);g.fillRect(x0,y0,w,hy-y0);
  g.fillStyle=GRAD(g,0,hy,0,y1,[[0,mix('#16305a',mix('#1a5fa0','#35a5dc',dw),dw)],[1,mix('#061532','#145a98',dw)]]);g.fillRect(x0,hy,w,y1-hy);
  if(dw<.55)for(let i=0;i<40;i++){const sx=x0+((i*53)%w),sy=y0+((i*31)%(hy-y0-4));if(((i+Math.floor(t*.002))%4))rect(g,sx,sy,1.5,1.5,'rgba(255,255,255,'+(.7*(1-dw)).toFixed(2)+')')}
  const k=Math.max(0,Math.min(1,(hh-5.2)/14.6));
  if(dw>.02){const sx=x0+w*(.15+.7*k),sy=hy-10-Math.sin(k*Math.PI)*(hy-y0-22);glowAt(g,sx,sy,90,'rgba(255,240,190,'+(.7*dw)+')');g.fillStyle=dusk>.2?'#ffd08a':'#fff6c8';g.beginPath();g.arc(sx,sy,10,0,7);g.fill();
   for(let i=0;i<14;i++){const yy=hy+3+i*3.2,ww=Math.max(3,26-i*1.4)*(.7+.3*Math.sin(t*.004+i));rect(g,sx-ww/2+Math.sin(t*.003+i)*2,yy,ww,1.5,'rgba(255,248,210,'+(.55*dw)+')')}}
  else{const mx=x0+w*.72,my=y0+24;glowAt(g,mx,my,70,'rgba(210,225,255,.5)');g.fillStyle='#f4f6ff';g.beginPath();g.arc(mx,my,9,0,7);g.fill();g.fillStyle='#10163a';g.beginPath();g.arc(mx+4,my-2,8,0,7);g.fill();
   for(let i=0;i<10;i++){const yy=hy+3+i*3.6;rect(g,mx-8+Math.sin(t*.003+i)*3,yy,14-i,1.5,'rgba(220,232,255,.35)')}}
  // เกาะไกล ๆ
  g.fillStyle=mix('#0c1c34','#5a7d9a',dw);g.beginPath();g.moveTo(x0+w*.60,hy);g.quadraticCurveTo(x0+w*.66,hy-24,x0+w*.74,hy-8);g.quadraticCurveTo(x0+w*.80,hy-18,x0+w*.88,hy);g.fill();
  g.fillStyle=mix('#0a1a2e','#4c6f8c',dw);g.beginPath();g.moveTo(x0+w*.05,hy);g.quadraticCurveTo(x0+w*.12,hy-14,x0+w*.22,hy);g.fill();
  // คลื่น
  for(let r=0;r<8;r++){const yy=hy+5+r*((y1-hy-6)/8);for(let x=x0+((r*37)%50);x<x1;x+=46){const a=.10+.10*Math.sin(t*.003+x*.05+r);rect(g,x+Math.sin(t*.002+r)*6,yy,16+r*2,1.6,'rgba(255,255,255,'+(a*(.4+dw*.6)).toFixed(3)+')')}}
  // เรือใบ
  {const bx=x0+((t||0)*.006%(w+120))-60,by=hy+10;rect(g,bx,by+6,22,4,mix('#14203a','#f2f2f2',dw));rect(g,bx+10,by-14,2,20,mix('#14203a','#ddd',dw));g.fillStyle=mix('#1c2a4a','#ffffff',dw);g.beginPath();g.moveTo(bx+12,by-13);g.lineTo(bx+12,by+4);g.lineTo(bx+24,by+4);g.closePath();g.fill();g.fillStyle=mix('#1c2a4a','#ffd9d0',dw);g.beginPath();g.moveTo(bx+9,by-9);g.lineTo(bx+9,by+4);g.lineTo(bx+1,by+4);g.closePath();g.fill()}
  // นกนางนวล
  if(dw>.3){for(let i=0;i<3;i++){const bx=x0+((t||0)*.02*(1+i*.3)+i*180)%(w+60)-30,by=y0+16+i*9+Math.sin(t*.004+i)*3;g.strokeStyle='rgba(250,250,250,.8)';g.lineWidth=1.3;g.beginPath();g.moveTo(bx-5,by);g.quadraticCurveTo(bx-2,by-4,bx,by);g.quadraticCurveTo(bx+2,by-4,bx+5,by);g.stroke()}}
  g.restore();
 }
