const sInP=(x,y,P)=>{let c=false;for(let i=0,j=P.length-1;i<P.length;j=i++){const a=P[i],b=P[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c}return c};
const sInR=(x,y,r)=>x>=r[0]&&x<=r[2]&&y>=r[1]&&y<=r[3];
const BCH_PLAZA=[[6,112],[48,112],[50,252],[340,252],[372,242],[392,242],[392,270],[360,284],[340,302],[300,332],[284,340],[210,346],[6,346]];
const BCH_GAP=[[158,336],[228,336],[228,396],[158,396]];
const BCH_SAND=[[0,392],[165,392],[212,404],[244,430],[270,468],[298,508],[340,548],[410,584],[452,596],[0,596]];
const BCH_PIER=[[[392,238],[878,238],[878,282],[392,282]],[[345,312],[392,284],[640,284],[640,334],[402,334],[378,328]],[[600,282],[650,282],[656,330],[600,330]],[[600,330],[656,330],[696,420],[696,468],[600,468]]];
