 {const pl=.5+.5*Math.sin(t*.006);g.fillStyle='rgba(255,226,140,'+(.10+.14*pl).toFixed(2)+')';g.fillRect(160,340,66,52);g.strokeStyle='rgba(255,236,170,'+(.5+.4*pl).toFixed(2)+')';g.lineWidth=2;g.strokeRect(161,341,64,50);g.font='bold 16px sans-serif';g.textAlign='center';g.fillStyle='rgba(255,244,200,'+(.65+.35*pl).toFixed(2)+')';g.fillText('▲',193,376-pl*5);g.fillText('▲',193,360-pl*5);g.textAlign='start'}
 // ลูกค้าเดินสวนตามลูกศร: ป้ายบอกทางขึ้นบันได
 {const pl=.5+.5*Math.sin(t*.006);g.fillStyle='rgba(255,226,140,'+(.12+.2*pl).toFixed(2)+')';g.fillRect(6,112,44,40);g.font='bold 14px sans-serif';g.fillStyle='rgba(255,240,190,'+(.6+.4*pl).toFixed(2)+')';g.textAlign='center';g.fillText('▲',28,142-pl*4);g.font='bold 9px sans-serif';g.fillText('สี่แยก',28,106);g.textAlign='start'}
 if(night>.02){g.fillStyle='rgba(8,16,52,'+(night*.5).toFixed(3)+')';g.fillRect(0,0,W,H);
  BCH_LAMPS.forEach((p,i)=>{const f=.8+.2*Math.sin(t*.004+i);const gr=g.createRadialGradient(p[0],p[1],2,p[0],p[1],46);gr.addColorStop(0,'rgba(255,214,120,'+(.55*night*f).toFixed(3)+')');gr.addColorStop(1,'rgba(255,190,90,0)');g.fillStyle=gr;g.fillRect(p[0]-46,p[1]-46,92,92)})}
