function scnTrans(tr,dt){
 if(tr.type==='dlg')return true;
 if(tr.type==='seaBoard'){const ok=walkTo(900,262,95,dt);setFade(Math.max(0,Math.min(1,(tr.t-.5)/.8)));if((ok&&tr.t>1.2)||tr.t>3){st.moving=0;st.trans=null;enter('sea',{from:'pier'})}return true}
 if(tr.type==='walkPath'){
  setFade(Math.max(0,1-tr.t/.7));
  const p=tr.pts[tr.i];if(!p){st.moving=0;st.trans=null;setFade(0);return true}
  if(walkTo(p[0],p[1],tr.sp||105,dt))tr.i++;
  return true}
 if(tr.type==='crossLeave'){
  const V={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]}[tr.dir];
  st.x+=V[0]*135*dt;st.y+=V[1]*135*dt;st.dir=tr.dir==='left'?1:tr.dir==='right'?3:tr.dir==='up'?2:0;st.moving=1;st.frame=(st.frame+135*dt/CEO_STRIDE)%4;
  setFade(Math.min(1,Math.max(0,(tr.t-.1)/.6)));
  if(tr.t>=.8){st.moving=0;st.trans=null;
   if(tr.dir==='left')enter('street',{from:'cross'});else if(tr.dir==='right')enter('carst',{from:'cross'});else if(tr.dir==='up')enter('aqst',{from:'cross'});else enter('beach',{from:'cross'})}
  return true}
 return false;
}
