/* ===== v148 · สี่แยกมีชีวิต: รถวิ่งในเลน + สัญญาณไฟ + คนเดินบนทางเท้า/ทางม้าลาย ===== */
const CX_COLS=['#d94b4b','#3f7fd9','#f0c63a','#e8e8ea','#4caf6a','#8a5cc2','#2f3542','#e58a2b'];
const CX_LANE={S:{x:396,a:'y',s:1},N:{x:328,a:'y',s:-1},E:{y:313,a:'x',s:1},W:{y:372,a:'x',s:-1}};
const CX_LINE={S:224,N:480,E:194,W:526};
const CX_NODES={E1:[40,256],L1:[225,268],T1:[284,252],T2:[442,252],R1:[495,268],E2:[920,256],L2:[225,414],B1:[284,448],B2:[442,448],R2:[495,418],E3:[920,420],E4:[140,428],E5:[262,568],E6:[478,568]};
const CX_EDGES=[['E1','L1'],['L1','T1'],['T1','T2','x'],['T2','R1'],['R1','E2'],['L1','L2','x'],['R1','R2','x'],['L2','B1'],['L2','E4'],['B1','E5'],['B1','B2','x'],['B2','R2'],['R2','E3'],['B2','E6']];
const CX_ZONES=[[296,228,424,274],[296,426,424,472],[196,282,254,402],[466,282,524,402]];   // ทางม้าลาย
function cxInit(){
 const pool=bwPool().slice(),peds=[],names=Object.keys(CX_NODES);
 const n=3+(Math.random()<.5?1:0);
 for(let i=0;i<n&&pool.length;i++){
  const sp=pool.splice(Math.floor(Math.random()*pool.length),1)[0],nm=names[Math.floor(Math.random()*names.length)],p=CX_NODES[nm];
  peds.push({kind:sp.kind,id:sp.id,x:p[0],y:p[1],d:0,f:Math.random()*4,v:0,from:nm,to:null,wait:sRnd(0,3)});
 }
 st.cx={cars:[],peds,ph:0,pt:0,sp:1.5,last:0};
}
const CX_PH=[['NS',9],['AR',1.8],['EW',9],['AR',1.8]];
function cxGate(dir){const ph=CX_PH[st.cx.ph][0];return dir==='S'||dir==='N'?ph==='NS':ph==='EW'}
function cxPedOK(cross){ // เดินข้ามถนนได้เมื่อรถแกนที่ตัดผ่านติดไฟแดงและเหลือเวลาพอ
 const c=st.cx,ph=CX_PH[c.ph][0],left=CX_PH[c.ph][1]-c.pt;
 return (cross==='h'?ph==='EW':ph==='NS')&&left>4.2;
}
function cxFront(c){const h=(c.len||40)/2;return c.d==='S'?c.y+h:c.d==='N'?c.y-h:c.d==='E'?c.x+h:c.x-h}
function cxStep(dt){
 const c=st.cx;c.pt+=dt;if(c.pt>=CX_PH[c.ph][1]){c.pt=0;c.ph=(c.ph+1)%4}
 const day=sceneDaylight()>.1;
 c.sp-=dt;
 if(c.sp<=0){c.sp=(day?sRnd(2.2,4.6):sRnd(6,10));
  if(c.cars.length<7){const d='EW'[Math.floor(Math.random()*2)],L=CX_LANE[d],o={d,t:carPick(),v:sRnd(40,60),vmax:sRnd(62,86),fa:Math.random()*60,brake:0};o.len=Math.round(CAR_DEF[o.t].len*.82);
   if(L.a==='y'){o.x=L.x;o.y=d==='S'?-30:630}else{o.y=L.y;o.x=d==='E'?-30:990}
   const f=cxFront(o);if(!c.cars.some(q=>q.d===d&&Math.abs(cxFront(q)-f)<70+o.len))c.cars.push(o)}}
 const walkers=[{x:st.x,y:st.y,p:1}].concat(c.peds.map(p=>({x:p.x,y:p.y})));
 c.cars.forEach(o=>{
  const L=CX_LANE[o.d],vertical=L.a==='y',sg=L.s,f=cxFront(o);let vt=o.vmax;
  // สัญญาณไฟ: หยุดหน้าเส้นถ้ายังไม่ถึงเส้นและไฟแดง
  const line=CX_LINE[o.d],dist=(line-f)*sg;
  if(dist>=-1&&dist<130&&!cxGate(o.d)){vt=Math.min(vt,Math.max(0,Math.sqrt(2*95*Math.max(0,dist-1))))}
  // รถคันหน้าในเลนเดียวกัน
  c.cars.forEach(q=>{if(q===o||q.d!==o.d)return;const qp=vertical?q.y:q.x,op=vertical?o.y:o.x;if((qp-op)*sg<=0)return;const gap=(qp-sg*(q.len/2)-f)*sg;if(gap<90)vt=Math.min(vt,Math.max(0,(gap-14)*2.6))});
  // คน/ผู้เล่นอยู่ข้างหน้า
  walkers.forEach(w=>{const ahead=vertical?(w.y-f)*sg:(w.x-f)*sg,lat=Math.abs(vertical?w.x-L.x:w.y-L.y);
   if(ahead>-10&&ahead<(w.p?78:62)&&lat<(w.p?26:20))vt=Math.min(vt,Math.max(0,(ahead-18)*3))});
  const dv=vt-o.v;o.v+=dv*Math.min(1,dt*(dv<0?4.5:1.6));if(o.v<1&&vt<1)o.v=0;o.brake=dv<-3||o.v<3?1:0;
  o.fa+=o.v*dt*.6;if(vertical)o.y+=sg*o.v*dt;else o.x+=sg*o.v*dt;
 });
 c.cars=c.cars.filter(o=>o.x>-60&&o.x<1020&&o.y>-60&&o.y<660);
 // คนเดินเท้า
 c.peds.forEach(p=>{
  if(p.wait>0){p.wait-=dt;p.v=0;return}
  if(!p.to){
   const opts=CX_EDGES.filter(e=>e[0]===p.from||e[1]===p.from);let e=opts[Math.floor(Math.random()*opts.length)];
   if(opts.length>1&&p.prev){const o2=opts.filter(q=>!(q[0]===p.prev||q[1]===p.prev));if(o2.length)e=o2[Math.floor(Math.random()*o2.length)]}
   const to=e[0]===p.from?e[1]:e[0];
   if(e[2]){const cross=(p.from==='T1'||p.from==='T2'||p.from==='B1'||p.from==='B2')?'h':'v';if(!cxPedOK(cross)){p.wait=.5;return}}
   p.to=to;p.cross=e[2]?1:0}
  const q=CX_NODES[p.to],dx=q[0]-p.x,dy=q[1]-p.y,d=Math.hypot(dx,dy),sp=Math.min(d,(p.cross?52:40)*dt);
  if(d<1.5){p.prev=p.from;p.from=p.to;p.to=null;p.cross=0;p.wait=sRnd(.5,4);return}
  p.x+=dx/d*sp;p.y+=dy/d*sp;p.v=40;p.f+=dt*6;p.d=Math.abs(dx)>=Math.abs(dy)?(dx<0?1:3):(dy<0?2:0);
 });
}
function cxCar(g,o,night){ // ใช้โมเดลรถจริงของเกม (สไปรต์เดียวกับรถบนถนน/โชว์รูม)
 const el=CAR_EL[o.t],d=CAR_DEF[o.t];if(!el||!el.complete||!el.naturalWidth)return;
 const k=.82*d.len/d.w0,dw=d.cw*k,dh=d.ch*k,fi=o.v>3?Math.floor(o.fa/26)%(d.nf||3):0;
 const a={N:-Math.PI/2,S:Math.PI/2,E:0,W:0}[o.d],row=o.d==='W'?0:1,fw=o.d==='W'?-1:1;
 g.save();g.translate(Math.round(o.x),Math.round(o.y));g.rotate(a);
 g.fillStyle='rgba(0,0,0,.28)';g.beginPath();g.ellipse(0,dh*.18,dw*.46,dh*.3,0,0,6.283);g.fill();
 if(night>.05){const gr=g.createLinearGradient(fw*dw*.45,0,fw*(dw*.45+70),0);gr.addColorStop(0,'rgba(255,240,180,'+(.42*night).toFixed(2)+')');gr.addColorStop(1,'rgba(255,240,180,0)');g.fillStyle=gr;g.beginPath();g.moveTo(fw*dw*.45,-6);g.lineTo(fw*(dw*.45+70),-24);g.lineTo(fw*(dw*.45+70),24);g.lineTo(fw*dw*.45,6);g.fill()}
 g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';
 g.drawImage(el,fi*d.cw,row*d.ch,d.cw,d.ch,-dw/2,-dh*.62,dw,dh);
 g.restore();
}
function cxSignal(g,x,y,on){ // เสาไฟจราจรขนาดเล็ก
 g.fillStyle='#20242e';g.fillRect(x-4,y-14,8,22);g.fillStyle='#0b0d12';g.fillRect(x-3,y-13,6,20);
 const col=on==='g'?['#400','#430','#3f6']:on==='y'?['#400','#fb3','#130']:['#f43','#430','#130'];
 g.fillStyle=col[0];g.fillRect(x-2,y-12,4,4);g.fillStyle=col[1];g.fillRect(x-2,y-7,4,4);g.fillStyle=col[2];g.fillRect(x-2,y-2,4,4);
}
function crsLive(g,t,front){
 if(!st.cx)cxInit();
 const c=st.cx;
 if(!front){
  const dt=c.last?Math.min(.05,(t-c.last)/1000):0;c.last=t;cxStep(dt);
  const ph=CX_PH[c.ph][0],yl=ph==='AR';
  const ns=ph==='NS'?'g':yl?'y':'r',ew=ph==='EW'?'g':yl?'y':'r';
  cxSignal(g,282,236,ns);cxSignal(g,444,468,ns);cxSignal(g,214,292,ew);cxSignal(g,512,396,ew);
  const night=1-sceneDaylight();
  c.cars.slice().sort((a,b)=>a.y-b.y).forEach(o=>cxCar(g,o,night));
 }
 c.peds.filter(p=>front?p.y>=st.y:p.y<st.y).sort((a,b)=>a.y-b.y).forEach(w=>{
  g.fillStyle='rgba(0,0,0,.25)';g.beginPath();g.ellipse(w.x,w.y-1,13,4.5,0,0,6.283);g.fill();
  try{drawStreetNPC(g,w,t)}catch(e){}
 });
}
function crsFront(g,t){crsLive(g,t,1)}

