 let CUTON=null;
 function cut(id,done,mark){
  css();(mark||LS().cut)[id]=1;sv();
  if(CUTON)CUTON.fin(1);
  const C=CUTS[id],ov=document.createElement('div');ov.id='lostCut';
  ov.innerHTML='<canvas width="320" height="180"></canvas><div class="sub"></div><button class="skip" type="button">⏭ ข้าม</button>';
  document.body.appendChild(ov);
  const cv=ov.querySelector('canvas'),g=cv.getContext('2d'),sub=ov.querySelector('.sub');g.imageSmoothingEnabled=false;
  try{st.keys={};if(window.JOY){JOY.x=0;JOY.y=0}}catch(e){}
  const c=mg();if(c)try{SND[id](c,c.currentTime+.05)}catch(e){}
  const t0=performance.now();let raf=0,ended=0;
  const fin=(force)=>{
   if(ended)return;ended=1;cancelAnimationFrame(raf);clearTimeout(tm);removeEventListener('keydown',kd,true);
   if(MG&&AC){try{MG.gain.setTargetAtTime(0,AC.currentTime,.06);const m=MG;setTimeout(()=>{try{m.disconnect()}catch(e){}},500)}catch(e){}}
   ov.remove();CUTON=null;if(!force&&done)try{done()}catch(e){console.error(e)}
  };
  const kd=e=>{if(e.key==='Escape'||e.key==='Enter'||e.key===' '){e.preventDefault();e.stopImmediatePropagation();fin()}};
  addEventListener('keydown',kd,true);
  ov.querySelector('.skip').addEventListener('click',e=>{e.stopPropagation();fin()});
  ov.querySelector('.skip').addEventListener('pointerdown',e=>e.stopPropagation());
  const tm=setTimeout(()=>fin(),C.D*1000+1500);
  const loop=()=>{
   if(ended)return;const t=(performance.now()-t0)/1000;
   try{g.clearRect(0,0,320,180);C.draw(g,t);g.textAlign='start'}catch(e){console.error(e)}
   const s=C.sub.find(x=>t>=x[0]&&t<x[1]);sub.textContent=s?s[2]:'';
   if(t>=C.D){fin();return}
   raf=requestAnimationFrame(loop);
  };
  CUTON={fin};loop();
 }
 /* ---------- ไอคอนหลักฐาน (พิกเซล 48x48) ---------- */
 const ICO={};
 function sym(g,x,y,s,col){g.strokeStyle=col||'#c89d4b';g.lineWidth=Math.max(1,s/8);g.beginPath();g.arc(x,y,s,0,6.283);g.stroke();for(let i=0;i<3;i++){const a=i*2.094-1.57;g.beginPath();g.moveTo(x,y);g.lineTo(x+Math.cos(a)*s,y+Math.sin(a)*s);g.stroke()}}
 function icon(id){
  if(ICO[id])return ICO[id];
  const cv=document.createElement('canvas');cv.width=cv.height=48;const g=cv.getContext('2d');g.imageSmoothingEnabled=false;
  const P=(c,x,y,w,h)=>{g.fillStyle=c;g.fillRect(x,y,w,h)};
  const paper=(c1)=>{P('#3d2a16',5,5,38,38);P(c1||'#e8d9a8',6,6,36,36)};
  if(id==='E1'){paper();P('#2f7ab0',8,30,32,10);P('#4d6b3a',14,24,20,8);P('#3b2f22',22,10,5,16);P('#3b2f22',20,8,9,3);sym(g,24,30,5,'#7a1f1f');P('#c0392b',34,36,3,3)}
  else if(id==='E2'){P('#101c38',4,4,40,40);g.fillStyle='#cfd8e6';g.beginPath();g.ellipse(24,24,15,11,0.5,0,6.283);g.fill();g.fillStyle='#9fb4d6';g.beginPath();g.ellipse(21,22,8,6,0.5,0,6.283);g.fill();sym(g,24,24,6,'#2f4f8a')}
  else if(id==='E3'){P('#1a2a4a',4,4,40,40);P('#7fd4c0',16,16,16,24);P('#a8e8d8',18,14,12,4);P('#6a4a2a',20,8,8,7);P('#e8d9a8',20,20,8,14);P('#7a1f1f',22,24,4,2)}
  else if(id==='E4'){P('#3d2a16',6,5,36,38);P('#7a5230',8,7,32,34);P('#e8d9a8',12,9,24,30);for(let i=0;i<5;i++)P('#3b2f22',14,13+i*5,16-i%2*4,1);P('#101c38',28,32,10,10);P('#e8d9a8',26,30,4,2)}
  else if(id==='E5'){P('#101c38',4,4,40,40);P('#c89d4b',20,8,8,4);g.fillStyle='#e0b455';g.beginPath();g.moveTo(24,12);g.quadraticCurveTo(38,16,38,34);g.lineTo(10,34);g.quadraticCurveTo(10,16,24,12);g.fill();P('#7a5a20',8,34,32,3);P('#3b2f22',22,37,4,4);g.strokeStyle='#6fb0ff';g.beginPath();g.arc(24,24,18,-0.5,0.5);g.stroke();g.beginPath();g.arc(24,24,22,-0.4,0.4);g.stroke()}
  else if(id==='E6'){paper('#d8c690');P('#2f7ab0',8,8,10,6);P('#2f7ab0',30,34,10,6);g.fillStyle='#e8d9a8';g.fillRect(14,16,22,16);g.globalAlpha=.4;sym(g,26,24,6,'#5b4a2a');g.globalAlpha=1;P('#c0392b',10,36,2,2)}
  else if(id==='E7'){P('#101c38',4,4,40,40);P('#c4c4cc',14,10,20,28);P('#3b3b4a',16,14,16,6);P('#e8d9a8',16,24,16,10);P('#7a1f1f',20,28,8,1);P('#7a1f1f',20,31,6,1)}
  else if(id==='E8'){P('#0a1226',4,4,40,40);g.strokeStyle='#c89d4b';g.lineWidth=3;g.beginPath();g.arc(24,24,16,0,6.283);g.stroke();g.lineWidth=1;g.fillStyle='#e0455f';g.beginPath();g.moveTo(34,12);g.lineTo(26,24);g.lineTo(22,22);g.fill();g.fillStyle='#dfe6f5';g.beginPath();g.moveTo(14,36);g.lineTo(26,24);g.lineTo(22,22);g.fill();P('#ffd45a',23,23,3,3)}
  else {paper('#efe2b8');for(let i=0;i<6;i++)P('#3b2f22',11,11+i*4,22-(i%3)*3,1);P('#7a1f1f',28,34,8,5);sym(g,32,36,3,'#e8d9a8')}
  return ICO[id]=cv.toDataURL();
 }
 /* ---------- ภารกิจ ---------- */
 function adv(mi,ki){
  const L=LS();if(L.cur!==mi||L.k!==ki||L.done)return false;
  L.k++;const M=LM[mi];
  if(L.k>=M.ob.length)finishM(mi);else{sv()}
  chipUpd();return true;
 }
 function giveEv(id,logTitle,logText){
  const L=LS();if(!L.ev[id]){L.ev[id]=S.day||1;ping();banner('🔎 ได้รับหลักฐานใหม่: '+EV[id].n,'ดูได้ในสมุดภารกิจ → แท็บ เบาะแส',icon(id))}
  if(logTitle&&!L.log.some(x=>x.t===logTitle))L.log.push({m:L.cur,t:logTitle,x:logText||''});
  sv();
 }
 function finishM(mi){
  const L=LS(),M=LM[mi];
  if(!L.rew[mi]){L.rew[mi]=1;try{S.money+=M.rw;S.tot.earn+=M.rw}catch(e){}try{hud()}catch(e){}}
  L.cur=mi+1;L.k=0;
  if(mi>=LM.length-1){L.cur=LM.length}
  sv();
  if(mi<LM.length-1)setTimeout(()=>banner('✅ ภารกิจสำเร็จ: '+M.n,'รางวัล ฿'+M.rw+' · ปลดล็อก “'+LM[mi+1].n+'”'),500);
 }
