 function puzzle(a){
  const ev=['ออกเรือตอนรุ่งเช้า น้ำทะเลนิ่งผิดปกติ ไม่มีลมเลยสักนิด','เห็นแสงไฟลึกเข้าไปในหมอก ได้ยินเสียงระฆังกลางทะเล','พบเกาะ… แต่ “ฉันเห็นมันแล้ว...แต่เกาะนั้นไม่ได้อยู่ตรงที่มันควรจะอยู่”'];
  let got=[];
  const show=(msg)=>{
   const order=[0,1,2].filter(i=>!got.includes(i)).sort(()=>Math.random()-.5);
   dlg({name:'สมุดบันทึก',tag:'เรียงเหตุการณ์ตามลำดับเวลา',emoji:'📔',
    text:(msg?msg+'\n':'')+'แตะเหตุการณ์ตามลำดับก่อน→หลัง (ข้อที่ '+(got.length+1)+'/3)'+(got.length?'\nเรียงแล้ว: '+got.map(i=>(i+1)+'.').join(' '):''),
    btns:order.map(i=>[ev[i].slice(0,34)+(ev[i].length>34?'…':''),()=>{
     if(i===got.length){got.push(i);if(got.length===3){seq([['N','เรียงลำดับถูกต้อง — บรรทัดสุดท้ายของสมุด: “ฉันเห็นมันแล้ว...แต่เกาะนั้นไม่ได้อยู่ตรงที่มันควรจะอยู่”'],['C','พ่อ… ท่านเห็นมันจริง ๆ']],()=>{giveEv('E4','สมุดบันทึกของชาวประมง','“ฉันเห็นมันแล้ว...แต่เกาะนั้นไม่ได้อยู่ตรงที่มันควรจะอยู่” — บรรทัดสุดท้ายของพ่อกัปตัน');a()})}else show('✔ ถูกต้อง!')}
     else{got=[];show('✘ ลำดับยังไม่ตรงกับวันที่ในสมุด ลองใหม่อีกครั้ง')}}])});
  };
  show('');
 }
 function theEnd(){
  const L=LS();L.done=1;L.ach=1;sv();
  css();const e=document.createElement('div');e.id='lostEnd';
  e.innerHTML='<p>บางครั้ง...การค้นพบความจริง อาจน่ากลัวยิ่งกว่าการไม่รู้อะไรเลย</p><h1>THE END — PART 1</h1><p>🏆 ความสำเร็จ: THE ISLAND SEEKER<br>เก็บหลักฐานครบ '+Object.keys(L.ev).length+'/9 ชิ้น · รางวัลพิเศษ ฿5,000</p><button type="button">กลับสู่เกม</button>';
  document.body.appendChild(e);void e.offsetWidth;e.classList.add('on');
  e.querySelector('button').addEventListener('click',()=>{e.classList.remove('on');setTimeout(()=>e.remove(),1700);SEA.course='cruise';chipUpd()});
  try{S.rep=(typeof S.rep==='number')?S.rep+2:S.rep}catch(x){}
 }
 /* ---------- ตัวเลือกเมื่อคุยกับ NPC ---------- */
 function curOb(){const L=peek();if(!L||!L.on||L.done||L.cur>=LM.length)return null;return LM[L.cur].ob[L.k]||null}
 function seaGo(ob){
  const L=LS();
  if(ob.night&&!isNight()){seq([['C','ต้องรอให้ถึงช่วงค่ำก่อนครับ (19:00–05:00) ตอนนี้ทะเลยังไม่เงียบพอ ตอนนี้เวลา '+clock()]],()=>{});return}
  const d=Math.hypot(SEA.x-ob.p[0],SEA.y-ob.p[1]);
  if(d<110&&(SEA.mode==='cruise'||SEA.mode==='depart')){runSea(ob,L.cur,L.k);return}
  seq([['C',ob.night?'ได้ครับ คืนนี้ทะเลดูแปลก ๆ… มุ่งหน้าไปตามพิกัดเลย':'รับทราบครับ มุ่งหน้าไปตามพิกัดที่บันทึกไว้']],()=>{SEA.course='lost';SEA.lt=ob.p.slice();SEA.tgt=SEA.lt;SEA.isl=0;toast('🧭 เรือมุ่งหน้าไปยังพิกัดที่ระบุ…')});
 }
 function runSea(ob,mi,ki){
  const L=LS();if(L.cur!==mi||L.k!==ki)return;
  SEA.course='hold';SEA.lt=null;
  ob.r(()=>{
   if(adv(mi,ki)){
    const n=curOb();
    if(n&&n.w==='sea'&&n.p===ob.p&&(!n.night||isNight()))setTimeout(()=>{const o2=curOb();if(o2===n)runSea(n,LS().cur,LS().k)},400);
    else if(SEA.course==='hold')SEA.course='cruise';
   }else if(SEA.course==='hold')SEA.course='cruise';
  });
 }
 function btns(who){
  const ob=curOb();if(!ob)return[];
  const ok=ob.w===who||(who==='cap'&&ob.w==='sea');
  if(!ok)return[];
  const L=LS(),mi=L.cur,ki=L.k;
  if(ob.w==='sea')return[[ob.b,()=>seaGo(ob)]];
  return[[ob.b,()=>{const o=curOb();if(o!==ob)return;ob.r(()=>adv(mi,ki))}]];
 }
 /* ---------- ท่าเรือ: จุดตรวจ + ตัวเริ่มเรื่อง ---------- */
 let ARRB=0;
 function spotOf(ob){return ob&&ob.sp?SPOT[ob.sp]:null}
 function beachAct(){
  if(SDLG||st.fish||st.place!=='beach'||CUTON)return false;
  const ob=curOb();if(!ob||!ob.sp)return false;
  const p=spotOf(ob);if(!p||Math.hypot(st.x-p[0],(st.y-p[1])*1.1)>58)return false;
  const L=LS(),mi=L.cur,ki=L.k;ob.r(()=>adv(mi,ki));return true;
 }
 function beachTick(g,t){
  const L=peek();if(!L)return;
  if(L.pend&&st.place==='beach'&&!ARRB&&!SDLG){
   ARRB=1;
   setTimeout(()=>{
    if(st.place!=='beach'||!LS().pend){ARRB=0;return}
    narr('บางสิ่งที่หายไป...\nอาจไม่เคยจากไปไหนเลย',()=>{
     const L2=LS();L2.on=1;L2.pend=0;L2.cur=0;L2.k=0;sv();ARRB=0;
     banner('📖 เรื่องราวใหม่: THE LOST ISLAND','ภารกิจแรก “แสงไฟที่ไม่มีเจ้าของ” — คุยกับกัปตันเรือ · เปิดสมุดภารกิจ → แท็บ ภารกิจ');chipUpd();
    },5600);
   },1100);
  }
  const ob=curOb();if(!ob||!ob.sp||st.place!=='beach')return;
  const p=spotOf(ob);if(!p)return;
  const near=Math.hypot(st.x-p[0],(st.y-p[1])*1.1)<58,bob=Math.sin(t*.006)*3;
  g.save();g.textAlign='center';
  if(ob.sp==='bottle'){ // ขวดแก้วเล็ก ๆ ที่เสาท่าเรือ
   g.fillStyle='rgba(0,0,0,.25)';g.fillRect(p[0]-9,p[1]+3,18,3);
   g.fillStyle='#7fd4c0';g.fillRect(p[0]-3,p[1]-9,6,11);g.fillStyle='#a8e8d8';g.fillRect(p[0]-2,p[1]-12,4,4);g.fillStyle='#e8d9a8';g.fillRect(p[0]-1,p[1]-6,2,6);
  }
  g.globalAlpha=.55+.45*Math.sin(t*.008);g.fillStyle='#ffe39b';g.beginPath();g.arc(p[0]+10,p[1]-14+bob*.3,2.2,0,6.283);g.fill();g.globalAlpha=1;
  g.font='bold 16px sans-serif';g.fillStyle='#ffd45a';g.strokeStyle='#2b1a05';g.lineWidth=3;g.strokeText('❗',p[0],p[1]-26+bob);g.fillText('❗',p[0],p[1]-26+bob);
  if(near){g.font='bold 11px "Noto Sans Thai",sans-serif';const tx='E · '+ob.b.replace(/^\S+\s/,'');g.lineWidth=3;g.strokeText(tx,p[0],p[1]-42);g.fillStyle='#fff';g.fillText(tx,p[0],p[1]-42)}
  g.restore();
 }
 function seaTick(){
  const ob=curOb();
  if(!ob||ob.w!=='sea'||SEA.course!=='lost'||!SEA.lt||SDLG||CUTON)return;
  if(SEA.mode!=='cruise')return;
  if(Math.hypot(SEA.x-ob.p[0],SEA.y-ob.p[1])<75){const L=LS();runSea(ob,L.cur,L.k)}
 }
 function intercept(cb){
  const L=peek();if((L&&(L.cut.pro||L.on||L.done||L.pend)))return false;
  const l=LS();l.cut.pro=1;l.pend=1;sv();
  SEA.course='hold';scnDlgClose(1);
  cut('pro',()=>seq([['P','เมื่อกี้นั่นอะไรน่ะ?'],['C','แปลก...ตรงนั้นไม่ควรมีอะไรอยู่เลย'],['P','หมายความว่ายังไง?'],['C','ฉันขับเรือผ่านแถวนี้มาเกือบ 20 ปี แต่ไม่เคยเห็นแสงแบบนั้นมาก่อน']],cb));
  return true;
 }
 /* ---------- ชิปภารกิจ + สมุด ---------- */
 let CH=null;
 function chipUpd(){
  css();
  if(!CH){CH=document.createElement('div');CH.id='lostChip';document.body.appendChild(CH);
   CH.addEventListener('click',()=>{try{QUEST.openJ();setTimeout(()=>{const b=document.querySelector('#qJ .qTabs button[data-tab="'+(rpeek()&&curO()&&st.place!=='sea'?'M':'L')+'"]');if(b)b.click()},30)}catch(e){}})}
  const L=peek(),ob=curOb(),Rm=rpeek(),ro=curO();
  const showR=Rm&&ro&&st.active&&!SDLG&&!CUTON&&(st.place==='street'||st.place==='beach'||st.place==='sea'||st.place==='cross'||st.place==='farm');
  const show=L&&L.on&&!L.done&&ob&&(st.place==='beach'||st.place==='sea')&&!SDLG&&!CUTON;
  if(showR){CH.textContent='🌌 ริมุรุ '+(Rm.cur+1)+'/5 · '+ro.t;CH.classList.add('on')}
  else if(show){CH.textContent='🏝️ '+(L.cur+1)+'/10 · '+ob.t;CH.classList.add('on')}else CH.classList.remove('on');
 }
 setInterval(chipUpd,600);
 function html(J){
  const L=LS();
  const nav=['📜 ภารกิจ','🔎 หลักฐาน','📖 บันทึกเรื่องราว'].map((s,i)=>'<button data-lost="pg:'+i+'" class="'+(L.pg===i?'on':'')+'">'+s+'</button>').join('');
  let b='';
  if(L.pg===0){
   b=LM.map((M,i)=>{
    const dn=i<L.cur||L.done,cur=i===L.cur&&!L.done,lk=i>L.cur&&!L.done;
    const stt=dn?'COMPLETED':cur?(L.k>0?'IN_PROGRESS':'AVAILABLE'):'LOCKED';
    if(lk)return '<div class="lsM lk"><i>'+stt+'</i><b>ภารกิจ '+String(i+1).padStart(2,'0')+'</b> 🔒 ???</div>';
    return '<div class="lsM '+(cur?'cur':'dn')+'"><i>'+stt+'</i><b>ภารกิจ '+String(i+1).padStart(2,'0')+' · '+esc(M.n)+'</b>'+
     (cur?'<div style="margin-top:4px">'+esc(M.s)+'</div><ul>'+M.ob.map((o,k)=>'<li class="'+(k<L.k?'ok':k===L.k?'now':'')+'">'+(k<L.k?'✔ ':k===L.k?'▶ ':'· ')+esc(o.t)+'</li>').join('')+'</ul><div style="margin-top:4px;color:#9fb4d6">รางวัล: ฿'+M.rw+' + หลักฐาน</div>':'<div style="margin-top:3px;color:#9fb4d6">รางวัลที่ได้รับ ฿'+M.rw+'</div>')+'</div>';
   }).join('')+(L.ach?'<div class="lsM cur"><b>🏆 THE ISLAND SEEKER</b> — จบ “THE END — PART 1” แล้ว</div>':'');
  }else if(L.pg===1){
   const keys=Object.keys(EV),sel=L.sel&&L.ev[L.sel]?L.sel:null;
   b='<div class="lsG">'+keys.map(k=>L.ev[k]?'<button data-lost="ev:'+k+'" class="'+(sel===k?'on':'')+'" title="'+esc(EV[k].n)+'"><img src="'+icon(k)+'"></button>':'<button class="lk" disabled>?</button>').join('')+'</div>'+
    (sel?'<div class="lsE"><img src="'+icon(sel)+'"><div><b style="color:#ffd45a">'+esc(EV[sel].n)+'</b><p>'+esc(EV[sel].d)+'</p></div></div>':'<div class="qEm">แตะหลักฐานเพื่ออ่านรายละเอียดอีกครั้ง · เก็บแล้ว '+Object.keys(L.ev).length+'/9</div>');
  }else{
   b=L.log.length?L.log.map(x=>'<div class="lsL"><b>ภารกิจ '+(x.m+1)+' · '+esc(x.t)+'</b>'+esc(x.x)+'</div>').join(''):'<div class="qEm">ยังไม่มีบันทึก</div>';
  }
  return '<div class="qBd2"><div class="qDt" style="padding:10px"><div class="lsNav">'+nav+'</div>'+b+'</div></div>';
 }
