 for(let i=0;i<7;i++){const a=t*.0014+i*0.9,r=26+Math.sin(t*.003+i)*6;g.globalAlpha=.6+.4*Math.sin(t*.005+i);g.fillStyle='#cfe8ff';g.fillRect(Math.round(x+Math.cos(a)*r),Math.round(y-34+Math.sin(a*1.3)*34),2,2)}
 g.restore();
