  if(!R.acc||R.done===0&&curO()&&curO().k!=='items'||(curO()&&curO().k==='final')){g.fillStyle='#ffe39b';g.strokeText('✨ MYTHIC',p.x,p.y-96);g.fillText('✨ MYTHIC',p.x,p.y-96);g.font='bold 20px sans-serif';g.fillStyle='#ffd45a';const by=p.y-108+Math.sin(t*.006)*2;g.strokeText('!',p.x,by);g.fillText('!',p.x,by)}
