      let sfx='';if(k===R.k&&o.k==='items'){const n=o.n||o.items.length;sfx=' ('+o.items.filter(itemOK).length+'/'+n+')';const w=o.items.find(x=>x.t==='work');if(w)sfx=' ('+itemDoneN(w)+'/'+w.need+')'}
