  g.fillStyle='#16264a';g.fillRect(70,20,100,13);g.fillStyle='#c89d4b';g.fillRect(70,20,100,1);g.fillRect(70,32,100,1);
  g.save();g.font='bold 10px "Courier New",monospace';g.textAlign='center';g.fillStyle='#ffe39b';g.fillText('MY COMPANY',120,30);g.restore();
