  {const hh=sceneHour(),f=Math.max(0,Math.min(1,(hh-5.2)/14)),X=120+f*700,Y=170-Math.sin(f*Math.PI)*110;g.fillStyle='rgba(255,224,142,'+dl.toFixed(3)+')';g.beginPath();g.arc(X,Y,38,0,7);g.fill()}
