  kidPanel().hidden=false;st.keys={};try{if(window.JOY){JOY.x=0;JOY.y=0}}catch(e){}
  st.talk={i,mode:'menu',acts:[]};st.moving=0;
  const h=sceneHour(),sleepy=h>=21||h<6?' (หาวนิด ๆ) ':'';
  kidSay(sleepy+KID_DEF[i].greet[kidLv(kidAff(i))]);kidReact(i,'happy');kidRender();
