 // ============================================================================
 // v95 · ระบบจราจรฉากถนนคนเดิน (รถ NPC จากภาพที่แนบ · เวลาเกม · รถเมล์ · ทางม้าลาย · แตร)
 // ============================================================================
 const CAR_IMG={"truck": "assets/img/0956cfcea7e4.png", "sedan": "assets/img/fe551857a870.png", "pickup": "assets/img/30544b51ec0a.png", "taxi": "assets/img/f2546831a465.png"};
 const CAR_DEF={
  sedan:{len:130,cw:275,ch:100,w0:273,wt:.30},
  taxi:{len:134,cw:269,ch:108,w0:268,wt:.25},
  pickup:{len:150,cw:269,ch:132,w0:265,wt:.25},
  truck:{len:205,cw:271,ch:144,w0:269,wt:.20}
 };
 const CAR_EL={};Object.keys(CAR_DEF).forEach(k=>{const i=new Image();i.src=CAR_IMG[k];CAR_EL[k]=i});
 try{CARX.CARS.forEach(c=>{CAR_DEF[c.id]={len:c.tlen,cw:c.cw,ch:c.ch,w0:c.cw,wt:c.wt,nf:2,car:1};CAR_EL[c.id]=c.img})}catch(e){console.error('[carx traffic]',e)}
 const CAR_LANE=[{dir:-1,y:512},{dir:1,y:440}];   // เลนบน = วิ่งไปซ้าย · เลนล่าง (เลนรถเมล์) = วิ่งไปขวา
 const CAR_ZONES=[[440,525],[440,525]];               // ทางม้าลาย (พิกัดโลก x)
 const CAR_ROAD={y0:338,y1:536},CAR_MAX=8,CAR_GAP=30,CAR_STOPLINE=14;
 const CARFX=(()=>{
  let AC=null,cur=null,tag=null;
  const on=()=>{try{return localStorage.getItem('mct_sound')!=='0'}catch(e){return true}};
  const vol=()=>{try{const v=localStorage.getItem('mct_vol');if(v==null)return .8;const n=+v;return Math.max(0,Math.min(1,n>1?n/100:n))}catch(e){return .8}};
  function ctx(){if(!on())return null;try{if(!AC){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;AC=new C()}if(AC.state==='suspended')AC.resume();return AC}catch(e){return null}}
  function stop(){if(!cur)return;const c=cur;cur=null;tag=null;try{const t=c.c.currentTime;c.g.gain.cancelScheduledValues(t);c.g.gain.setTargetAtTime(0,t,.02);c.o1.stop(t+.12);c.o2.stop(t+.12)}catch(e){}}
  function honk(dur,pitch,who){ // แตร 2 โทน · เล่นทีละเสียงเท่านั้น (เสียงใหม่ตัดเสียงเก่า ไม่ซ้อน)
   stop();const c=ctx();if(!c)return;
   try{const t=c.currentTime,o1=c.createOscillator(),o2=c.createOscillator(),f=c.createBiquadFilter(),g=c.createGain(),pk=.07*vol()+.0002;
    o1.type='square';o2.type='square';o1.frequency.value=380*pitch;o2.frequency.value=480*pitch;f.type='lowpass';f.frequency.value=1700;
    g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(pk,t+.02);g.gain.setValueAtTime(pk,t+Math.max(.03,dur-.06));g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    o1.connect(f);o2.connect(f);f.connect(g);g.connect(c.destination);o1.start(t);o2.start(t);o1.stop(t+dur+.05);o2.stop(t+dur+.05);
    const me={c,g,o1,o2};cur=me;tag=who;o1.onended=()=>{if(cur===me){cur=null;tag=null}}}catch(e){cur=null;tag=null}
  }
  return{honk,stop,tag:()=>tag};
 })();
 const trafficOpen=()=>true;      // เกิดรถเฉพาะ 09:00–19:59 (เวลาในเกม)
 const carR=(a,b)=>a+Math.random()*(b-a);
 // พิกัดตามทิศทางวิ่ง: s เพิ่มขึ้นเมื่อรถเดินหน้า (ไปขวา s=x · ไปซ้าย s=W-x)
 const carF=c=>c.dir>0?c.x+c.w:W-c.x, carRr=c=>c.dir>0?c.x:W-(c.x+c.w);
 const carSetS=(c,sf)=>{c.x=c.dir>0?sf-c.w:W-sf};
 function carPick(){let sid=null;try{sid=CARX.cur()&&CARX.cur().id}catch(e){}const ids=Object.keys(CAR_DEF).filter(i=>i!==sid);let tot=0;ids.forEach(i=>tot+=CAR_DEF[i].wt);let r=Math.random()*tot;for(const id of ids){r-=CAR_DEF[id].wt;if(r<=0)return id}return'sedan'}
 function carNew(lane,sf){
  const t=carPick(),d=CAR_DEF[t],L=CAR_LANE[lane],c={t,lane,dir:L.dir,y:L.y,w:d.len,sc:d.len/d.w0,v:0,vmax:carR(92,132),x:0,honk:0,honkT:'',fa:Math.random()*60,blocked:null,fin:null};
  carSetS(c,sf);return c;
 }
 const carClear=(cars,lane,sf,w,gap)=>!cars.some(o=>o.lane===lane&&carRr(o)<sf+gap&&carF(o)>sf-w-gap);
 function trafficNew(){return{cars:[],tr:{sp:[carR(.5,3),carR(2,6)],lock:0,pz:-1,crossHonk:true,crossT:0,dwell:0,dwellNeed:carR(8,12),hornAnext:0,aOn:false}}}
 function trafficPopulate(){
  const T=streetState;if(!T||!trafficOpen())return;
  const want=2+Math.floor(Math.random()*3);
  for(let i=0;i<want*5&&T.cars.length<want;i++){
   const lane=0,sf=carR(240,720),c=carNew(lane,sf);
   if(carClear(T.cars,lane,sf,c.w,70)){c.v=c.vmax*.85;T.cars.push(c)}
  }
 }
 function busSpawnClear(){const T=streetState;return !T||!T.cars||!T.cars.some(c=>c.lane===1&&c.x<60)}
 function busCarLimit(b){ // รถเมล์ต้องไม่ชนรถยนต์ที่อยู่ข้างหน้าในเลนเดียวกัน
  const T=streetState;if(!T||!T.cars)return 1e9;let lim=1e9;const bf=b.x+busW();
  T.cars.forEach(c=>{if(c.lane!==1||carF(c)<=b.x+4)return;const gap=c.x-bf;
   if(gap<120){const l=gap<14?0:Math.max(0,c.v+(gap-38)*1.6);if(l<lim)lim=l}});
  return lim;
 }
 // ผู้ที่อาจอยู่บนถนน = ผู้เล่น + เด็ก ๆ ที่เดินตาม (ใช้ตำแหน่งจริง)
 function carWalkers(){
  const a=[];if(!st.hidden)a.push({x:st.x,y:st.y,p:1});
  if(st.kg&&st.place==='street')st.kg.m.forEach(m=>a.push({x:m.x,y:m.y,p:0}));
  return a;
 }
 const inRoad=y=>y>=CAR_ROAD.y0&&y<=CAR_ROAD.y1;
 const carZoneS=(c,z)=>{const a=CAR_ZONES[z];return c.dir>0?[a[0],a[1]]:[W-a[1],W-a[0]]};
 function trafficStep(dt){
  const T=streetState;if(!T||!T.cars)return;
  const cars=T.cars,tr=T.tr,s=st.s,b=s&&s.bus,walk=carWalkers();
  const zocc=[false,false];let pz=-1;
  walk.forEach(w=>{if(!inRoad(w.y))return;for(let z=0;z<2;z++)if(w.x>=CAR_ZONES[z][0]-10&&w.x<=CAR_ZONES[z][1]+10){zocc[z]=true;if(w.p)pz=z}});
  // --- เกิดรถ (09:00–20:00 เท่านั้น · สุ่มเวลา · เว้นระยะ · จำกัดจำนวน) ---
  if(trafficOpen()){
   for(let lane=0;lane<1;lane++){
    tr.sp[lane]-=dt;
    if(tr.sp[lane]<=0){
     tr.sp[lane]=carR(3.5,9);
     if(cars.length<CAR_MAX){
      const c=carNew(lane,-6);
      const busNear=lane===1&&b&&b.x<c.w+90;
      if(!busNear&&carClear(cars,lane,-6,c.w,40)){c.v=c.vmax*.9;cars.push(c)}
     }
    }
   }
  }
  // --- จัดลำดับในเลนเพื่อหารถคันหน้า ---
  const byLane=[[],[]];cars.forEach(c=>byLane[c.lane].push(c));
  byLane.forEach(a=>a.sort((p,q)=>carF(q)-carF(p))); // คันหน้าสุดก่อน
  tr.lock-=dt;cars.forEach(c=>{if(c.honk>0)c.honk-=dt});
  // --- เคลื่อนที่ ---
  byLane.forEach((arr,lane)=>{arr.forEach((c,idx)=>{
   const sf=carF(c),lead=idx>0?arr[idx-1]:null;let cons=1e9,why=null,spot=null,fin=null;
   if(lead){cons=carRr(lead)-CAR_GAP;if(lead.fin!=null)spot=lead.fin-lead.w-CAR_GAP}   // spot = ตำแหน่งที่จะไปหยุดต่อแถวจริง ๆ (ทำนายล่วงหน้า)
   if(lane===1&&b&&sf<=b.x+8){const bc=b.x-CAR_GAP;if(bc<cons){cons=bc;why='bus'}if(b.state!=='depart'){const bs=busStopX()-CAR_GAP;spot=spot==null?bs:Math.min(spot,bs)}}   // รถเมล์ (จอด/ออกตัว) = รถคันหน้า
   fin=spot;
   for(let z=0;z<2;z++){const zs=carZoneS(c,z);if(sf>zs[0]-4)continue;const sl=zs[0]-CAR_STOPLINE;
    if(zocc[z]){if(sl<cons){cons=sl;why='cross'}fin=fin==null?sl:Math.min(fin,sl)}   // คน/เด็กอยู่บนทางม้าลาย → หยุดก่อนเส้น
    else if(spot!=null&&spot>zs[0]-2&&spot-c.w<zs[1]+2){if(sl<cons){cons=sl;why='zebra'}fin=Math.min(fin,sl)}}   // ที่ต่อแถวจะคาบทางม้าลาย → รอก่อนเส้น (ห้ามจอดบนลาย)
   // คนอยู่กลางถนนในเลนของรถ → หยุดก่อนชน
   for(const w of walk){if(!inRoad(w.y)||w.y<c.y-46||w.y>c.y+22)continue;const ps=c.dir>0?w.x:W-w.x;if(ps>sf-8&&ps-sf<170){const pc=ps-30;if(pc<cons){cons=pc;why='walker';fin=pc}}}
   let vmax=c.vmax;for(let z=0;z<2;z++){const zs=carZoneS(c,z);if(sf<zs[1]&&zs[0]-sf<120)vmax=Math.min(vmax,108)}
   const gap=cons-sf;let vt=vmax;
   if(cons<1e8)vt=gap<=0?0:Math.min(vmax,Math.sqrt(2*300*Math.max(0,gap-2)));
   if(lead&&gap<90)vt=Math.min(vt,Math.max(0,lead.v+Math.max(0,gap-6)*1.2));
   if(vt>c.v)c.v=Math.min(vt,c.v+85*dt);else c.v=Math.max(vt,c.v-340*dt);
   if(c.v<0)c.v=0;
   c.fin=fin;c.blocked=(why&&c.v<40&&gap<90)?why:null;
   let ns=sf+c.v*dt;
   if(cons<1e8&&sf<=cons+1&&ns>cons){ns=Math.max(sf,cons);c.v=Math.min(c.v,Math.max(0,(ns-sf)/Math.max(dt,1e-3)))}
   if(lead){const lim=carRr(lead)-8;if(ns>lim)ns=Math.max(sf,lim)}
   if(ns<sf)ns=sf;                       // ไม่ถอยหลัง
   c.fa+=ns-sf;carSetS(c,ns);
  })});
  // --- ลบรถที่พ้นขอบฉาก ---
  for(let i=cars.length-1;i>=0;i--){const c=cars[i];if(carRr(c)>W+20)cars.splice(i,1)}
  // --- แตร B: ผู้เล่นก้าวขึ้นทางม้าลาย → รถคันแรกที่หยุดรอ บีบสั้น ๆ ครั้งเดียวต่อการก้าวขึ้น ---
  if(pz!==tr.pz){tr.pz=pz;tr.crossHonk=pz<0;tr.crossT=0}
  if(pz>=0&&!tr.crossHonk){
   tr.crossT+=dt;
   if(tr.crossT>4)tr.crossHonk=true;
   else if(tr.lock<=0){
    const c=cars.filter(c=>c.blocked==='cross'&&c.v<30).sort((p,q)=>carF(q)-carF(p))[0];
    if(c){cars.forEach(o=>{o.honk=0});c.honk=.4;c.honkT='B';tr.lock=1.8;tr.crossHonk=true;tr.hornAnext=Math.max(tr.hornAnext,4);CARFX.honk(.28,1.08,'B')}
   }
  }
  // --- แตร A: รถเมล์จอดรอนาน (8–12 วิ) โดยไม่มีคนขึ้น → เฉพาะรถคันแรกที่ต่อแถวอยู่หลังรถเมล์ ---
  const aCond=!!(b&&!b.car&&b.state==='dwell'&&b.v===0&&!b.carry&&s.phase==='free'&&!s.committed);
  if(aCond){
   tr.aOn=true;tr.dwell+=dt;tr.hornAnext-=dt;
   if(tr.dwell>=tr.dwellNeed&&tr.hornAnext<=0&&pz<0&&tr.crossHonk&&tr.lock<=0){
    const c=byLane[1].filter(c=>carF(c)<=b.x-4&&b.x-carF(c)<CAR_GAP+70&&c.v<8)[0]; // คันหน้าสุดที่อยู่หลังรถเมล์
    if(c){c.honk=.6;c.honkT='A';tr.lock=1.6;tr.hornAnext=carR(6,9);CARFX.honk(.5,1,'A')}
    else tr.hornAnext=1.2;
   }
  }else if(tr.aOn){ // ขึ้นรถแล้ว / รถเมล์ออก / เลิกจอด → ยกเลิกสถานะรอและเสียงแตรทั้งหมด
   tr.aOn=false;tr.dwell=0;tr.hornAnext=0;tr.dwellNeed=carR(8,12);
   cars.forEach(c=>{if(c.honkT==='A')c.honk=0});if(CARFX.tag()==='A')CARFX.stop();
  }
 }
 function carDraw(g,t,c){
  const el=CAR_EL[c.t],d=CAR_DEF[c.t];if(!el.complete||!el.naturalWidth)return;
  const fi=c.v>3?Math.floor(c.fa/26)%(d.nf||3):0,row=c.dir<0?0:1,dw=d.cw*c.sc,dh=d.ch*c.sc,cx=c.x+c.w/2,shake=c.honk>0?Math.sin(c.honk*70)*.7:0;
  const dark=kfLerp(ST_DARK,streetMin()/60);
  g.save();g.fillStyle='rgba(0,0,0,.30)';g.beginPath();g.ellipse(cx,c.y-1,c.w*.47,5,0,0,Math.PI*2);g.fill();
  if(dark>.3){g.globalAlpha=Math.min(.35,dark*.5);g.fillStyle='#ffe9a8';const hx=c.dir>0?c.x+c.w:c.x;g.beginPath();g.ellipse(hx+c.dir*26,c.y-14,30,8,0,0,Math.PI*2);g.fill();g.globalAlpha=1}
  g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';
  g.drawImage(el,fi*d.cw,row*d.ch,d.cw,d.ch,Math.round(cx-dw/2),Math.round(c.y-dh+shake),dw,dh);
  if(c.honk>0){const s=c.honkT==='A'?'ปี๊นนน!':'ปี๊น!',tx=c.dir>0?c.x+c.w-10:c.x+10,ty=c.y-dh-6;g.font='bold 13px sans-serif';g.textAlign='center';g.lineWidth=3;g.strokeStyle='#172338';g.fillStyle='#ffe39b';g.strokeText(s,tx,ty);g.fillText(s,tx,ty)}
  g.restore();
 }
 function carObjs(g,t){const T=streetState;return T&&T.cars?T.cars.map(c=>({y:c.y,draw:()=>carDraw(g,t,c)})):[]}

 // ปิดฉากทันที (ใช้ตอนผีจับ/ย้ายฉากแบบฉุกเฉิน) โดยไม่ผ่านขั้นตอนปกติ
 function hardStop(){st.active=false;st.fish=null;st.trans=null;st.ride=null;st.pickTarget=null;st.kg=null;closeTalk(true);fadeTok++;streetState=null;st.s=null;st.hidden=false;hidePick();BSFX.engineStop();CARFX.stop();setFade(0);fadeIn=null;cancelAnimationFrame(st.raf);st.keys={}}
 // ===== เลิกงาน: CEO เดินออกจากบริษัท (ไม่มีหน้าต่างเลือกสถานที่) =====
 const lv={on:false,t:0,last:0,raf:0};
 function beginLeave(){
  if(lv.on||st.active)return;
  lv.on=true;lv.t=0;lv.last=0;lv.sp=0;CUT.on=1;try{clearPlayerInput()}catch(e){}
  cancelAnimationFrame(lv.raf);lv.raf=requestAnimationFrame(leaveLoop);
 }
 function leaveLoop(ts){
  if(!lv.on)return;
  const dt=Math.min(.05,(ts-(lv.last||ts))/1000);lv.last=ts;lv.t+=dt;
  const p=S.pl;
  // เดินต่อไปทางขวาออกจากหน้าบริษัท พร้อมเฟดภาพ แล้วต่อเนื่องไปฉากถนน
  if(window.OFC&&S.ofc&&OFC.doorAnim){if(!lv.sp){lv.sp=1;try{OFC.exitSpot(p)}catch(e){}}OFC.doorAnim(Math.min(1,lv.t/.3));if(lv.t<1.1){p.y+=80*dt;p.d=0;p.mv=true;p.f+=dt*8}else p.mv=false}else if(lv.t<1.1){p.x+=100*dt;p.d=3;p.mv=true;p.f+=dt*8}else p.mv=false;
  setFade((lv.t-.4)/.7);
  if(lv.t>=1.25){lv.on=false;p.mv=false;try{OFC.doorAnim(-1)}catch(e){}open();enter('street',{from:'office'});return}
  lv.raf=requestAnimationFrame(leaveLoop);
 }
