 // ---- เสียงประตู (สังเคราะห์ด้วย WebAudio · เคารพการตั้งค่าเสียงเดิม) ----
 const DSFX=(()=>{
  let AC=null,nb=null;
  const on=()=>{try{return localStorage.getItem('mct_sound')!=='0'}catch(e){return true}};
  const vol=()=>{try{const v=localStorage.getItem('mct_vol');return v==null?.8:Math.max(0,Math.min(1,(+v)/100))}catch(e){return .8}};
  function ctx(){if(!on())return null;try{if(!AC){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;AC=new C()}if(AC.state==='suspended')AC.resume();return AC}catch(e){return null}}
  function noise(c){if(nb)return nb;const n=c.sampleRate*2,b=c.createBuffer(1,n,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;return nb=b}
  function tone(f0,f1,dur,type,v,delay){const c=ctx();if(!c)return;try{const t=c.currentTime+(delay||0),o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
   g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v*vol()+.0002,t+Math.min(.02,dur/3));g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur+.03)}catch(e){}}
  function hiss(fc,dur,v,delay,type,q){const c=ctx();if(!c)return;try{const t=c.currentTime+(delay||0),s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=noise(c);f.type=type||'bandpass';f.frequency.value=fc;f.Q.value=q||1;
   g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v*vol()+.0002,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+dur);s.connect(f);f.connect(g);g.connect(c.destination);s.start(t);s.stop(t+dur+.05)}catch(e){}}
  return{
   knob(){tone(1500,900,.05,'square',.05,0);tone(1100,650,.06,'square',.05,.09);hiss(2600,.05,.05,.01,'highpass',1)},
   open(){tone(150,92,.75,'sawtooth',.03,0);tone(310,180,.6,'triangle',.018,.05);hiss(900,.7,.05,0,'bandpass',4)},
   close(){tone(120,70,.5,'sawtooth',.022,0);hiss(700,.5,.035,0,'bandpass',4)},
   thud(){tone(95,38,.22,'sine',.16,0);hiss(420,.2,.12,0,'lowpass',.8);tone(1300,800,.04,'square',.03,.02)}
  };
 })();
