   if(from==='beach'){st.x=480;st.y=590;st.dir=2;st.trans={type:'arrive',t:0,toX:480,toY:462};setFade(1)}
   else if(from==='stst'){st.x=-26;st.y=404;st.dir=3;st.trans={type:'arrive',t:0,toX:100,toY:404};setFade(1)}
