 function cancel(){st.active=false;st.fish=null;st.trans=null;st.ride=null;st.pickTarget=null;st.kg=null;closeTalk(true);fadeTok++;streetState=null;st.s=null;st.hidden=false;hidePick();BSFX.engineStop();CARFX.stop();setFade(0);fadeIn=null;document.getElementById('ceoBag').hidden=true;cancelAnimationFrame(st.raf);st.keys={};el().classList.remove('show','choosing');CUT.on=0;if(window.OFC&&OFC.floor&&S.ofc)OFC.placeCeoEntry();else{S.pl.x=14*T+12;S.pl.y=15*T+16;S.pl.mv=false}}
 function returnOffice(){
   if(st.sleep||st.trans||st.ride||st.talk)return;                       // กำลังเปลี่ยนฉาก/นอน = กดซ้ำไม่ได้
   if(st.place==='condo'){beginCondoLeave();return}             // คอนโด → เดินออกประตู → ทางเดินคอนโด (ไม่วาร์ป)
   if(st.place==='hall'){beginHallStairs();return}              // ทางเดิน → เดินไปบันไดลง → รถเมล์ → บริษัท
   if(st.place==='beach'){beginBeachLeave();return}
   if(st.place==='cross'){crossLeave('left');return}
   if(st.place==='sea'){seaReturnAsk();return}
   if(st.place==='carst'){carstLeave(-1);return}
   if(st.place==='aqst'){aqstLeave(-1);return}
    if((st.place==='cardst'||st.place==='cardin'||st.place==='aucin'||st.place==='snkst'||st.place==='snkin'||st.place==='ncst'||st.place==='ncin'||st.place==='stst'||st.place==='stin'||st.place==='frst'||st.place==='dpfr'||st.place==='cave')&&window.CARDSHOP_SCENE){CARDSHOP_SCENE.back();return}
   if(st.place==='farm'){farmLeaveBegin();return}
   if(st.place==='aqin'){aqOutBegin();return}
   if(st.place==='showroom'){beginShowOut();return}             // ทะเล → เดินออกทางซ้าย → ถนนคนเดิน (ไม่กลับบริษัทตรง ๆ)
   if(st.place==='street'&&st.s){
    if(st.s.phase!=='free')return;
    if(ghostBusy()){toast('🚪 ประตูบริษัทถูกล็อก! ผีกำลังไล่ตาม · วิ่งไปขึ้นรถเมล์ที่ป้ายเพื่อเอาตัวรอด');return}
    // เดินกลับ: เดินไปตามทางเท้าออกขอบซ้ายของฉาก (สลับทางกับตอนเดินเข้า) แล้วเฟดเข้าบริษัท
    {const s=st.s,x=st.x,y=st.y,pts=[];if(y>331){pts.push([x,568]);pts.push([COMPANY.x,568]);pts.push([COMPANY.x,322])}else{pts.push([x,322]);pts.push([COMPANY.x,322])}pts.push([COMPANY.x,COMPANY.outY]);pts.push([COMPANY.x,COMPANY.doorY]);
     s.ex={pts,i:0};s.phase='toOffice';st.keys={};try{if(window.JOY){JOY.x=0;JOY.y=0}}catch(e){}
     return}
   }
   cancel();toast('กลับเข้าสู่บริษัทแล้ว')}
 function interact(){
  if(!st.active||st.mode!=='scene'||st.sleep||st.trans||st.ride||st.talk)return;
   if(bagOpen())return;
   if(st.place==='sea'){seaInteract();return}
   if(window.RIM&&RIM.act())return;
   if(boothAt()){callOpen();return}
   if(st.place==='hall'){hallInteract();return}
   if(st.place==='farm'){farmInteract();return}
   if((st.place==='cardst'||st.place==='cardin'||st.place==='aucin'||st.place==='snkst'||st.place==='snkin'||st.place==='ncst'||st.place==='ncin'||st.place==='stst'||st.place==='stin'||st.place==='frst'||st.place==='dpfr'||st.place==='cave')&&window.CARDSHOP_SCENE){CARDSHOP_SCENE.interact();return}
    if(st.place==='aqst'||st.place==='aqin'){aqInteract();return}
   if(st.place==='carst'||st.place==='showroom'){showInteract();return}
   if(st.place==='street'&&st.s&&st.s.phase==='free'&&window.REL&&REL.streetInteract&&REL.streetInteract(st))return;
   if(st.fish){fishAct();return}
   if((st.place==='street'?(st.s&&st.s.phase==='free'):st.place==='beach')&&kidsNearIdx()>=0){openKidTalk();return}
   if(LOST.beachAct())return;
   if(bchNpcNear()){merTalk();return}
   if(bchBoatNear()){seaBoard();return}
   if(canFish()){startFish();return}
  const near=(x,y,w,h)=>Math.abs(st.x-x)<w&&Math.abs(st.y-y)<h;
  if(atExit()){returnOffice();return}
  if(st.place==='street'){streetInteract();return}
  if(st.place==='condo'){
   if(wardNear()){if(window.WARD)WARD.open();return}
   if(aqNear()){aqOpen();return}
   if(near(735,300,85,48)){OS.force=1;OS.open();return}
   else if(near(165,315,130,60)){startSleep();return}
   else if(near(525,410,112,55))toast('🛋️ CEO นั่งพักบนโซฟา');
   else if(near(830,430,90,55))toast('☕ CEO ชงกาแฟร้อนๆ หนึ่งแก้ว');
   else toast('🏠 ใกล้โต๊ะคอม = เปิดคอม · ใกล้เตียง = นอนข้ามไปเช้า 06:00 · ใกล้ตู้เสื้อผ้า = เปลี่ยนชุด');
  }else{
   if(near(700,525,95,60))toast('🔥 CEO นั่งผิงไฟ มองดาวบนท้องฟ้า');
   else if(near(238,530,100,55)||near(348,530,100,55))toast('🏖️ CEO นอนพักบนเก้าอี้ชายหาด');
   else if(st.y<470)toast('🌊 ตกปลาได้เฉพาะในทะเล · เดินขึ้นท่าเรือไม้แล้วกด E');
   else toast('🌙 ลมทะเลยามค่ำคืนพัดเย็นสบาย');
  }
 }
 function key(e,down){
  if(!st.active||st.mode!=='scene'||(typeof OS!=='undefined'&&OS.on)||st.sleep)return;let k=e.key.toLowerCase();
  const map={arrowup:'up',arrowdown:'down',arrowleft:'left',arrowright:'right'};k=map[k]||k;
   if(st.talk){e.preventDefault();if(down){if(k==='escape'){if(st.talk.boss){if(window.VIPX&&VIPX.isOpen())VIPX.close();else if(window.CARBOSS)CARBOSS.close()}else closeTalk()}else if(!st.talk.boss)kidHotkey(k)}return}
   if(st.ride){e.preventDefault();if(down&&st.ride.phase==='pick'&&(k==='1'||k==='e'||k==='enter'||k===' '))pickDest();return}
   if(st.trans){if(['up','down','left','right','w','a','s','d','e','enter','escape','b'].includes(k))e.preventDefault();return}
   if(bagOpen()){e.preventDefault();if(down&&(k==='b'||k==='escape'))toggleBag();return}
   if(down&&k==='b'){e.preventDefault();toggleBag();return}
   if(st.fish){if(k===' '||k==='w'||k==='up'||k==='e'||k==='enter'){e.preventDefault();if(st.fish.ph==='game'){if(down&&!st.fish.hold)fishAct();st.fish.hold=down}else if(down)fishAct();return}if(down&&k==='escape'){endFish('เก็บอุปกรณ์ตกปลาแล้ว');return}if(['down','left','right','s','a','d'].includes(k)){e.preventDefault();st.keys[k]=down}return}
  if(st.s&&st.s.phase==='pick'){e.preventDefault();if(down&&(k==='1'||k==='e'||k==='enter'||k===' '))pickDest();else if(down&&(k==='2'||k==='3'||k==='4'))pickExtra(+k-2);return}
   if(st.s&&['arrive','toOffice','toBeach','boardWalk','boarding','closing','depart','out'].includes(st.s.phase)){if(['up','down','left','right','w','a','s','d','e','enter','escape'].includes(k))e.preventDefault();return}
   if(['up','down','left','right','w','a','s','d','e','enter','escape'].includes(k))e.preventDefault();
  if(down&&(k==='e'||k==='enter')){interact();return}
  if(down&&k==='escape'){returnOffice();return}
  st.keys[k]=down;
 }
 addEventListener('keydown',e=>key(e,true),true);addEventListener('keyup',e=>key(e,false),true);
  addEventListener('blur',()=>{if(st.active)st.keys={}});
 document.querySelectorAll('[data-ceoscene]').forEach(b=>{
  const k=b.dataset.ceoscene;b.addEventListener('pointerdown',e=>{e.preventDefault();st.keys[k]=true});
  ['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>st.keys[k]=false));
 });
  // v91: เมืองเปิดตลอด 24 ชั่วโมง — ไม่มีการล็อกตามเวลา (เวลาเกม S.t ไม่ถูกรีเซ็ตเมื่อเปลี่ยนฉาก)
  function tryOpen(){beginLeave()}
  // v91: CEO หมดสติ (ผีจับ) → ย้ายไปนอนบนเตียงคอนโด แล้วใช้ลำดับ "นอนข้ามไปเช้า 06:00" เดิมของเกม
  function faint(){
   if(st.sleep)return false;
   if(st.active)hardStop();
   open();enter('condo');
   st.x=BED.x;st.y=BED.y;st.dir=0;st.keys={};
   camSnap(st.x,st.y);
   st.sleep={t:1.0,done:0,s0:S.t,fx:BED.x,fy:BED.y,tgt:S.t<360?360:1440+360,faint:1};
   return true;
  }
