 window.__CEO_CTX={st,W,H,enter,transLock,walkTo,setFade,drawCEO,drawStreetNPC,sceneDaylight,hour:()=>sceneHour(),toast:m=>toast(m)};
  return {fishApi:{start:()=>startFish(),end:m=>endFish(m),draw:(g,t)=>drawFishCEO(g,t),lv:g=>drawFishLv(g),bagFull:()=>bagFull()},aq:AQAPI,farm:FARMAPI,tank,bossLock,rideTo,startRide,open,tryOpen,faint,enter,cancel,returnOffice,interact,pickDest,armBus,street:streetInfo,doorPulse:streetDoorPulse,dbg:()=>({st,lv,BUS,STOP,COMPANY,tf:streetState,HALL,CEO_H,hall:hall()}),kidAtlas:id=>KID_EL[id]||null,kidPort:id=>KID_IMG[id]?KID_IMG[id].p:'',bag:toggleBag,bagPrev,fishList,testGive,testClear,testLv,fishLv,atCompany:()=>!st.active,shop:{FISH,FSH,bagArr,bagAdd,bagTake,BAG_N,BAG_MAX}};
