 u.bill={amount:Math.max(100,amount),issued:S.day,due:S.day+2,paid:false};u.water=0;u.power=0;u.lastBillDay=S.day;
 log('🧪 [TEST] สร้างบิลค่าน้ำค่าไฟ '+M(u.bill.amount)+' · ครบกำหนดวันที่ '+u.bill.due);
