 ent:()=>OX.ready()?OFC.ent():[3,15],entXY:()=>OX.ready()?OFC.entXY():[3*T+16,15*T+16],
 rw:()=>OX.ready()?OFC.L().recWait:[4,12],rf:()=>OX.ready()?OFC.L().recFace:2,door:()=>OX.ready()?OFC.L().door:[3,14],
