function askUpgrade(k){
 css();const u=UPG[k],r=reasons(k),o=st();
 const conds=[
  [o.unlocked.indexOf(k)<0,'ยังไม่เคยอัปเกรดชั้นนี้'],
  [!u.need||o.unlocked.indexOf(u.need)>=0,u.need?'ปลดล็อก Office LV.'+u.need+' แล้ว':'—'],
  [ceoLevel()>=u.ceoLv,'CEO Level '+u.ceoLv+' ขึ้นไป (ตอนนี้ Lv.'+ceoLevel()+')'],
  [S.money>=u.cost,'เงินเพียงพอ '+M(u.cost)+' (มี '+M(S.money)+')']];
 modal('<h2>OFFICE LV.'+k+'</h2><small>'+LAY[k].title+'</small><div class="ofcPrice">ราคา: '+u.cost.toLocaleString('en-US')+' บาท</div>'+
  '<b>เงื่อนไข</b><ul>'+conds.map(c=>'<li class="'+(c[0]?'ok':'no')+'">'+(c[0]?'✔ ':'✘ ')+c[1]+'</li>').join('')+'</ul>'+
  '<b>สิ่งที่จะได้รับ</b><ul>'+BENEFIT[k].map(x=>'<li>'+x+'</li>').join('')+'</ul>'+
  (r.length?'<div style="color:#ff8a8a;font-size:13px">⚠ '+r.join(' · ')+'</div>':'')+
  '<div class="ofcAct"><button class="btn" '+(r.length?'disabled':'')+' onclick="OFC.upgrade('+k+')">Upgrade</button><button class="btn" onclick="OFC.closeModal()">Cancel</button></div>');
}
function floorCard(k){
 const o=st(),un=o.unlocked.indexOf(k)>=0,on=o.cur===k,u=UPG[k];
 const sl=slotsOf(k);let built=0,used=0;if(un)sl.forEach(s=>{const q=slotStatus(k,s);if(q!=='unbuilt')built++;if(q==='used')used++});
 const nEmp=S.emp.filter(e=>(e.floor||1)===k).length;
 return '<div class="ofcFloor'+(on?' on':'')+'"><div><b>Office LV.'+k+'</b> <small>'+LAY[k].title+'</small>'+
  (on?'<span class="ofcTag">อยู่ที่นี่</span>':un?'<span class="ofcTag">ปลดล็อกแล้ว</span>':'<span class="ofcTag lock">🔒 ล็อก</span>')+
  '<br><small>ห้อง '+LAY[k].roomCount+' · Workstation '+(un?built+'/':'')+sl.length+' · พนักงานชั้นนี้ '+nEmp+'</small></div>'+
  (un?'<button class="btn" '+(on?'disabled':'')+' onclick="OFC.go('+k+')">'+(on?'ชั้นปัจจุบัน':'ไปชั้นนี้')+'</button>':
      '<button class="btn" onclick="OFC.askUpgrade('+k+')">อัปเกรด '+M(u.cost)+'<br><small>CEO Lv.'+u.ceoLv+'+</small></button>')+'</div>';
}
